package haexporterplugin;

import haexporterplugin.enums.CombatTaskTier;
import haexporterplugin.enums.DiaryTier;
import haexporterplugin.enums.PlayerLookupService;
import net.runelite.client.config.*;

@ConfigGroup("HAExporter")
public interface HAExporterConfig extends Config
{
	// Note: keyNames are persisted settings. Change names/descriptions freely, but never rename a keyName.

	String MASTER_SWITCH_NOTE = "<br/>Applies to <i>all</i> connections: when off, this is disabled in the side panel too.";

	/* ============================
       Config Section Setup
       ============================ */

	@ConfigSection(
			name = "General",
			description = "How often and how quickly data is sent to Home Assistant",
			position = 100
	)
	String generalSection = "General";

	@ConfigSection(
			name = "Data Sharing",
			description = "Which parts of your player state are sent with every update",
			position = 200,
			closedByDefault = true
	)
	String dataSection = "Data Sharing";

	@ConfigSection(
			name = "Loot",
			description = "Which drops are sent as loot events",
			position = 300
	)
	String lootSection = "Loot";

	@ConfigSection(
			name = "Level Up",
			description = "Which level-ups are sent as events",
			position = 400,
			closedByDefault = true
	)
	String levelSection = "Level Up";

	@ConfigSection(
			name = "Collection Log",
			description = "Which new collection log slots are sent as events",
			position = 500,
			closedByDefault = true
	)
	String clogSection = "Collection Log";

	@ConfigSection(
			name = "Achievement Diary",
			description = "Which achievement diary tasks are sent as events",
			position = 600,
			closedByDefault = true
	)
	String diarySection = "Achievement Diary";

	@ConfigSection(
			name = "Combat Tasks",
			description = "Which combat achievement tasks are sent as events",
			position = 700,
			closedByDefault = true
	)
	String combatTaskSection = "Combat Tasks";

	@ConfigSection(
			name = "Deaths",
			description = "Death events",
			position = 800,
			closedByDefault = true
	)
	String deathSection = "Deaths";

	@ConfigSection(
			name = "Superior Spawns",
			description = "Superior slayer monster spawn events",
			position = 850,
			closedByDefault = true
	)
	String superiorSection = "Superior Spawns";

	@ConfigSection(
			name = "Just for Fun",
			description = "Silly extras that have nothing to do with Home Assistant",
			position = 950,
			closedByDefault = true
	)
	String funSection = "Just for Fun";

	/* ============================
       General
       ============================ */

	@Range(
			min = 1
	)
	@ConfigItem(
			keyName = "sendRate",
			name = "Update rate (ticks)",
			description = "Game ticks between regular state updates (1 tick = 0.6s, so 100 is about a minute).<br/>" +
					"Events such as drops and deaths are always sent right away",
			position = 101,
			section = generalSection
	)
	default int sendRate() {return 100;}

	@ConfigItem(
			keyName = "sendHealthInstantly",
			name = "Instant health updates",
			description = "When on, every health change is sent right away.<br/>" +
					"When off, health is only sent with the regular update",
			position = 102,
			section = generalSection
	)
	default boolean sendHealthInstantly() {
		return true;
	}

	@ConfigItem(
			keyName = "sendPrayerInstantly",
			name = "Instant prayer updates",
			description = "When on, every prayer point change is sent right away.<br/>" +
					"When off, prayer is only sent with the regular update",
			position = 103,
			section = generalSection
	)
	default boolean sendPrayerInstantly() {
		return true;
	}

	@ConfigItem(
			keyName = "sendSpecialWorldData",
			name = "Special world data",
			description = "Send data while playing on special or event worlds (Leagues, Deadman, tournament, beta, quest speedrunning, PvP Arena).<br/>" +
					"These use separate or temporary characters, so this is off by default: nothing is sent from them.",
			position = 104,
			section = generalSection
	)
	default boolean sendSpecialWorldData() {
		return false;
	}

	/* ============================
       Data Sharing
       ============================ */

	@ConfigItem(
			keyName = "includeInventory",
			name = "Share inventory",
			description = "Send the contents of your inventory." + MASTER_SWITCH_NOTE,
			position = 201,
			section = dataSection
	)
	default boolean includeInventory() {
		return true;
	}

	@ConfigItem(
			keyName = "includeEquipment",
			name = "Share equipment",
			description = "Send your worn equipment." + MASTER_SWITCH_NOTE,
			position = 202,
			section = dataSection
	)
	default boolean includeEquipment() {
		return true;
	}

	@ConfigItem(
			keyName = "includeActivePrayers",
			name = "Share active prayers",
			description = "Send the prayers you currently have turned on." + MASTER_SWITCH_NOTE,
			position = 203,
			section = dataSection
	)
	default boolean includeActivePrayers() {
		return true;
	}

	@ConfigItem(
			keyName = "includeLocation",
			name = "Share location",
			description = "Send your in-game coordinates and the trail of tiles you visited." + MASTER_SWITCH_NOTE,
			position = 204,
			section = dataSection
	)
	default boolean includeLocation() {
		return true;
	}

	/* ============================
       Loot
       ============================ */

	@ConfigItem(
			keyName = "includeLootEvents",
			name = "Send loot events",
			description = "Send an event when you receive a notable drop." + MASTER_SWITCH_NOTE,
			position = 301,
			section = lootSection
	)
	default boolean includeLootEvents() {
		return true;
	}

	@ConfigItem(
			keyName = "minLootValue",
			name = "Min item value (gp)",
			description = "Only send a drop when an item stack is worth at least this much",
			position = 302,
			section = lootSection
	)
	default int minLootValue() {
		return 25000;
	}

	@ConfigItem(
			keyName = "lootRarityThreshold",
			name = "Rarer than 1 in X",
			description = "Also send drops this rare, even when they are below the minimum value.<br/>" +
					"For example, 100 sends anything with a 1% drop rate or rarer.<br/>" +
					"Set to 0 to turn off. Only works for NPC drops and pickpocketing",
			position = 303,
			section = lootSection
	)
	default int lootRarityThreshold() {
		return 0;
	}

	@ConfigItem(
			keyName = "lootRarityValueIntersection",
			name = "Value AND rarity",
			description = "When on, a drop must pass <i>both</i> the minimum value and the rarity threshold.<br/>" +
					"Drops without known rarity only need to pass the minimum value",
			position = 304,
			section = lootSection
	)
	default boolean lootRarityValueIntersection() {
		return false;
	}

	@ConfigItem(
			keyName = "lootItemAllowlist",
			name = "Always send for these items",
			description = "These items are always sent, even when below the value or rarity threshold.<br/>" +
					"One item name per line, not case-sensitive. Use * as a wildcard (e.g. <i>*pet*</i>)",
			position = 305,
			section = lootSection
	)
	default String lootItemAllowlist() {
		return "";
	}

	@ConfigItem(
			keyName = "lootItemDenylist",
			name = "Never send for these items",
			description = "These items are never sent, whatever their value or rarity.<br/>" +
					"Wins over 'Always send for these items'.<br/>" +
					"One item name per line, not case-sensitive. Use * as a wildcard",
			position = 306,
			section = lootSection
	)
	default String lootItemDenylist() {
		return "";
	}

	@ConfigItem(
			keyName = "lootSourceDenylist",
			name = "Never send these sources",
			description = "Drops from these NPCs or activities are never sent.<br/>" +
					"One name per line, not case-sensitive.<br/>" +
					"Does <i>not</i> apply to player names for PK loot",
			position = 307,
			section = lootSection
	)
	default String lootSourceDenylist() {
		return "Einar\n";
	}

	@ConfigItem(
			keyName = "lootIncludePlayer",
			name = "Send PK loot",
			description = "Send loot you get from killing other players",
			position = 308,
			section = lootSection
	)
	default boolean lootIncludePlayer() {
		return true;
	}

	@ConfigItem(
			keyName = "lootIncludePkChest",
			name = "PK chest total value",
			description = "For PK loot chests, send when the <i>combined</i> value passes the minimum,<br/>" +
					"even if no single item does",
			position = 309,
			section = lootSection
	)
	default boolean lootIncludePkChest() {
		return true;
	}

	@ConfigItem(
			keyName = "lootIncludePickpocket",
			name = "Send pickpocket loot",
			description = "Send loot you get from pickpocketing",
			position = 310,
			section = lootSection
	)
	default boolean lootIncludePickpocket() {
		return true;
	}

	@ConfigItem(
			keyName = "playerLookupService",
			name = "Player lookup link",
			description = "Which website player names in PK loot events link to",
			position = 311,
			section = lootSection
	)
	default PlayerLookupService playerLookupService() {
		return PlayerLookupService.OSRS_HISCORE;
	}

	/* ============================
       Level Up
       ============================ */

	@ConfigItem(
			keyName = "includeLevelUpEvents",
			name = "Send level-up events",
			description = "Send an event when you gain a level." + MASTER_SWITCH_NOTE + "<br/>" +
					"Your skill levels are still shared with every update",
			position = 401,
			section = levelSection
	)
	default boolean includeLevelUpEvents() {
		return true;
	}

	@Range(
			min = 1,
			max = 127
	)
	@ConfigItem(
			keyName = "levelMinValue",
			name = "Minimum level",
			description = "Only send level-ups to this level or higher",
			position = 402,
			section = levelSection
	)
	default int levelMinValue() {
		return 1;
	}

	@Range(
			min = 1,
			max = 99
	)
	@ConfigItem(
			keyName = "levelInterval",
			name = "Send every Nth level",
			description = "Only send levels that are a multiple of this number (e.g. 5 sends 5, 10, 15...).<br/>" +
					"Level 99 is always sent",
			position = 403,
			section = levelSection
	)
	default int levelInterval() {
		return 1;
	}

	@ConfigItem(
			keyName = "levelIncludeVirtual",
			name = "Send virtual levels",
			description = "Send levels above 99 (virtual levels, up to 126, and 200M xp as 127)",
			position = 404,
			section = levelSection
	)
	default boolean levelIncludeVirtual() {
		return true;
	}

	@ConfigItem(
			keyName = "levelIncludeCombat",
			name = "Send combat level",
			description = "Send an event when your combat level goes up",
			position = 405,
			section = levelSection
	)
	default boolean levelIncludeCombat() {
		return true;
	}

	/* ============================
       Collection Log
       ============================ */

	@ConfigItem(
			keyName = "includeCollectionLogEvents",
			name = "Send clog events",
			description = "Send an event when you fill a new collection log slot." + MASTER_SWITCH_NOTE + "<br/>" +
					"Needs the in-game 'Collection log - New addition notification' setting to be on",
			position = 501,
			section = clogSection
	)
	default boolean includeCollectionLogEvents() {
		return true;
	}

	@ConfigItem(
			keyName = "clogMinValue",
			name = "Min item value (gp)",
			description = "Only send new collection log items worth at least this much.<br/>" +
					"Items without a GE price (such as pets) are always sent",
			position = 502,
			section = clogSection
	)
	default int clogMinValue() {
		return 0;
	}

	/* ============================
       Achievement Diary
       ============================ */

	@ConfigItem(
			keyName = "includeAchievementDiaryEvents",
			name = "Send diary events",
			description = "Send an event when you complete an achievement diary task." + MASTER_SWITCH_NOTE,
			position = 601,
			section = diarySection
	)
	default boolean includeAchievementDiaryEvents() {
		return true;
	}

	@ConfigItem(
			keyName = "diaryMinTier",
			name = "Minimum tier",
			description = "Only send diary tasks of this tier or harder",
			position = 602,
			section = diarySection
	)
	default DiaryTier diaryMinTier() {
		return DiaryTier.EASY;
	}

	/* ============================
       Combat Tasks
       ============================ */

	@ConfigItem(
			keyName = "includeCombatTaskEvents",
			name = "Send task events",
			description = "Send an event when you complete a combat achievement task." + MASTER_SWITCH_NOTE,
			position = 701,
			section = combatTaskSection
	)
	default boolean includeCombatTaskEvents() {
		return true;
	}

	@ConfigItem(
			keyName = "combatTaskMinTier",
			name = "Minimum tier",
			description = "Only send combat tasks of this tier or harder",
			position = 702,
			section = combatTaskSection
	)
	default CombatTaskTier combatTaskMinTier() {
		return CombatTaskTier.EASY;
	}

	/* ============================
       Deaths
       ============================ */

	@ConfigItem(
			keyName = "includeDeathEvents",
			name = "Send death events",
			description = "Send an event when you die, with the items kept and lost and who killed you." + MASTER_SWITCH_NOTE,
			position = 801,
			section = deathSection
	)
	default boolean includeDeathEvents() {
		return true;
	}

	/* ============================
       Superior Spawns
       ============================ */

	@ConfigItem(
			keyName = "includeSuperiorEvents",
			name = "Send superior events",
			description = "Send an event when a superior slayer monster appears." + MASTER_SWITCH_NOTE,
			position = 851,
			section = superiorSection
	)
	default boolean includeSuperiorEvents() {
		return true;
	}

	/* ============================
       Just for Fun
       ============================ */

	@ConfigItem(
			keyName = "kebab",
			name = "Kebab?",
			description = "Do you like kebab?",
			position = 951,
			section = funSection
	)
	default boolean kebab() {
		return false;
	}

	@ConfigItem(
			keyName = "garbage",
			name = "Garbage?",
			description = "Do you feel like garbage?",
			position = 952,
			section = funSection
	)
	default boolean garbage() {
		return false;
	}

	/* ============================
       Hidden Config Items
       ============================ */
	@ConfigItem(
			keyName = "homeassistantConnections",
			name = "Home Assistant Connections",
			description = "Stores all configured connections",
			hidden = true
	)
	default String homeassistantConnections()
	{
		return "[]"; // start empty as JSON array
	}

	@ConfigItem(
			keyName = "homeassistantConnections",
			name = "Home Assistant Connections",
			description = "Stores all configured connections",
			hidden = true
	)
	void setHomeassistantConnections(String value);
}

package haexporterplugin;

import com.google.gson.Gson;
import haexporterplugin.data.HAConnection;
import haexporterplugin.data.PairingException;
import haexporterplugin.data.TokenCallback;
import haexporterplugin.utils.ConfigUtils;
import haexporterplugin.utils.HomeAssistUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.text.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Slf4j
public class HAExporterPanel extends PluginPanel
{
    protected @Inject HAExporterConfig config;
    protected @Inject HomeAssistUtils homeAssistUtils;
    protected @Inject ConfigUtils configUtils;
    protected @Inject Gson gson;

    private final JPanel mainPanel = new JPanel(new BorderLayout());

    // Placeholder stats labels (update from singleton later)
    private final JLabel goldLabel = new JLabel("Gold Stored: 0");
    private final JLabel itemsLabel = new JLabel("Items Processed: 0");

    private final JLabel creditLabel = new JLabel("A plugin by: ");
    private final JLabel authorLabel = new JLabel("xXD4rkDragonXx & RedFireBreak");

    public final int CODE_LENGTH = 5;

    // Bundled images rather than Unicode symbols: the RuneScape font has no glyphs for those,
    // and macOS has no fallback font to borrow them from
    private static final ImageIcon SETTINGS_ICON = loadIcon("settings");
    private static final ImageIcon WARNING_ICON = loadIcon("warning");
    private static final ImageIcon PAUSE_ICON = loadIcon("pause");
    private static final ImageIcon CHECK_ICON = loadIcon("check");
    private static final ImageIcon CROSS_ICON = loadIcon("cross");

    // Pause indicators on the home view, refreshed every second while it is shown
    private final Map<JLabel, HAConnection> pauseLabels = new HashMap<>();
    private final Timer pauseTimer = new Timer(1000, e -> updatePauseLabels());

    public HAExporterPanel()
    {
        setLayout(new BorderLayout());
        add(mainPanel, BorderLayout.CENTER);
    }

    @Override
    public void onActivate()
    {
        super.onActivate();
        showHomeView(); // Rebuild the UI every time the panel is opened
    }

    @Override
    public void onDeactivate()
    {
        super.onDeactivate();
        pauseTimer.stop();
    }

    public void initialize()
    {
        showHomeView();
    }


    /* ============================
       HOME VIEW
       ============================ */

    private void showHomeView()
    {
        mainPanel.removeAll();

        JPanel container = new JPanel();
        container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
        container.setAlignmentX(Component.CENTER_ALIGNMENT);

        // Will be expanded on in a future release
        // container.add(buildStatsPanel());

        JPanel creditPanelWrapper = new JPanel();
        creditPanelWrapper.setLayout(new BoxLayout(creditPanelWrapper, BoxLayout.X_AXIS));
        creditPanelWrapper.setAlignmentX(Component.CENTER_ALIGNMENT);
        creditPanelWrapper.add(Box.createHorizontalGlue());
        JPanel creditPanel = buildCreditPanel();
        creditPanel.setAlignmentX(Component.CENTER_ALIGNMENT);
        creditPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, creditPanel.getPreferredSize().height));
        creditPanelWrapper.add(creditPanel);
        creditPanelWrapper.add(Box.createHorizontalGlue());
        container.add(creditPanelWrapper);

        container.add(Box.createVerticalStrut(15));

        JButton connectButton = new JButton("Connect New Device");
        connectButton.setAlignmentX(Component.CENTER_ALIGNMENT);
        connectButton.setMaximumSize(new Dimension(200, connectButton.getPreferredSize().height));
        connectButton.addActionListener(e -> showConnectionCodeInput());

        container.add(connectButton);
        container.add(Box.createVerticalStrut(15));

        JPanel connectionsPanel = buildConnectionsPanel();
        connectionsPanel.setAlignmentX(Component.CENTER_ALIGNMENT);
        connectionsPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        container.add(connectionsPanel);

        JPanel centerWrapper = new JPanel(new BorderLayout());
        centerWrapper.add(container, BorderLayout.CENTER);
        mainPanel.add(centerWrapper, BorderLayout.CENTER);

        revalidate();
        repaint();
    }

    private JPanel buildConnectionsPanel()
    {
        JPanel wrapper = new JPanel();
        wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
        wrapper.setBorder(BorderFactory.createTitledBorder("Connected Devices"));

        pauseTimer.stop();
        pauseLabels.clear();

        List<HAConnection> connections = configUtils.getStoredConnections();

        if (connections.isEmpty())
        {
            JLabel none = new JLabel("No devices connected.");
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            wrapper.add(none);
            return wrapper;
        }

        for (int i = 0; i < connections.size(); i++)
        {
            HAConnection connection = connections.get(i);

            JPanel card = new JPanel();
            card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
            card.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
            card.setAlignmentX(Component.LEFT_ALIGNMENT);

            // Header panel with name and settings button
            JPanel headerPanel = new JPanel(new BorderLayout());
            headerPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

            JLabel nameLabel = new JLabel(connection.getDisplayName());
            headerPanel.add(nameLabel, BorderLayout.WEST);

            JButton settingsButton = new JButton(SETTINGS_ICON);
            settingsButton.setPreferredSize(new Dimension(30, 20));
            settingsButton.setMargin(new Insets(0, 0, 0, 0));
            settingsButton.setToolTipText("Settings");
            settingsButton.addActionListener(e -> showConnectionSettings(connection));
            headerPanel.add(settingsButton, BorderLayout.EAST);

            card.add(headerPanel);

            if (connection.isEnabled())
            {
                // Pause indicator, hidden while the connection is delivering normally
                JLabel pauseLabel = new JLabel(PAUSE_ICON, SwingConstants.LEADING);
                pauseLabel.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));
                pauseLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
                updatePauseLabel(pauseLabel, connection);
                card.add(pauseLabel);
                pauseLabels.put(pauseLabel, connection);

                card.add(Box.createVerticalStrut(3));

                JLabel statusLabel = buildStatusLabel(connection);
                statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
                card.add(statusLabel);
            }
            else
            {
                // A disabled connection sends nothing, so the warning replaces the toggle status
                card.add(Box.createVerticalStrut(3));
                String reason = connection.getDisabledReason() != null
                        ? connection.getDisabledReason()
                        : "Disabled";
                JLabel disabledLabel = new JLabel(
                        "<html><span style='color:orange;'>" + reason + "</span></html>",
                        WARNING_ICON,
                        SwingConstants.LEADING
                );
                disabledLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
                card.add(disabledLabel);
            }

            wrapper.add(card);

            if (i < connections.size() - 1)
            {
                wrapper.add(Box.createVerticalStrut(5));
                JSeparator sep = new JSeparator(SwingConstants.HORIZONTAL);
                sep.setAlignmentX(Component.LEFT_ALIGNMENT);
                sep.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
                wrapper.add(sep);
                wrapper.add(Box.createVerticalStrut(5));
            }
        }

        if (!pauseLabels.isEmpty())
        {
            pauseTimer.restart();
        }

        return wrapper;
    }

    private void updatePauseLabels()
    {
        boolean homeViewShowing = false;
        for (Map.Entry<JLabel, HAConnection> entry : pauseLabels.entrySet())
        {
            Container card = entry.getKey().getParent();
            if (card != null && card.isShowing())
            {
                homeViewShowing = true;
                updatePauseLabel(entry.getKey(), entry.getValue());
            }
        }

        if (!homeViewShowing)
        {
            // Switched to the settings or pairing view, or the panel is hidden
            pauseTimer.stop();
        }
    }

    private void updatePauseLabel(JLabel label, HAConnection connection)
    {
        long remaining = homeAssistUtils.getPausedUntil(connection) - System.currentTimeMillis();
        if (remaining <= 0)
        {
            label.setVisible(false);
            return;
        }

        int queued = homeAssistUtils.getQueuedCount(connection);
        String text = "Paused \u2014 retrying in " + formatRemaining(remaining)
                + (queued > 0 ? " (" + queued + " queued)" : "");
        label.setText("<html><span style='color:orange;'>" + text + "</span></html>");
        label.setVisible(true);
    }

    private static String formatRemaining(long millis)
    {
        long seconds = (millis + 999) / 1000;
        return seconds < 60
                ? seconds + "s"
                : String.format("%dm %02ds", seconds / 60, seconds % 60);
    }

    private JLabel buildStatusLabel(HAConnection connection)
    {
        List<String> disabled = new ArrayList<>();

        if (!connection.isIncludeInventory() || !config.includeInventory()) disabled.add("Inv");
        if (!connection.isIncludeEquipment() || !config.includeEquipment()) disabled.add("Equip");
        if (!connection.isIncludeActivePrayers() || !config.includeActivePrayers()) disabled.add("Pray");
        if (!connection.isIncludeLocation() || !config.includeLocation()) disabled.add("Loc");
        if (!connection.isIncludeLootEvents() || !config.includeLootEvents()) disabled.add("Loot");
        if (!connection.isIncludeDeathEvents() || !config.includeDeathEvents()) disabled.add("Death");
        if (!connection.isIncludeLevelUpEvents() || !config.includeLevelUpEvents()) disabled.add("Lvl");
        if (!connection.isIncludeAchievementDiaryEvents() || !config.includeAchievementDiaryEvents()) disabled.add("Diary");
        if (!connection.isIncludeCombatTaskEvents() || !config.includeCombatTaskEvents()) disabled.add("Task");
        if (!connection.isIncludeSuperiorEvents() || !config.includeSuperiorEvents()) disabled.add("Superior");
        if (!connection.isIncludeCollectionLogEvents() || !config.includeCollectionLogEvents()) disabled.add("CollLog");

        if (disabled.isEmpty())
        {
            return new JLabel("All enabled", CHECK_ICON, SwingConstants.LEADING);
        }

        return new JLabel("<html>Disabled: " + String.join(", ", disabled) + "</html>", CROSS_ICON, SwingConstants.LEADING);
    }

    private void removeConnection(HAConnection connection)
    {
        int result = JOptionPane.showConfirmDialog(
                this,
                "Are you sure you want to remove \"" + connection.getDisplayName() + "\"?\n\nThis action cannot be undone.",
                "Remove Device - Confirm",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE
        );

        if (result != JOptionPane.YES_OPTION)
            return;

        List<HAConnection> connections = configUtils.getStoredConnections();
        connections.removeIf(c ->
                c.getBaseUrl().equals(connection.getBaseUrl())
                        && c.getToken().equals(connection.getToken())
        );

        config.setHomeassistantConnections(gson.toJson(connections));

        JOptionPane.showMessageDialog(
                this,
                "Device removed successfully.",
                "Success",
                JOptionPane.INFORMATION_MESSAGE
        );

        showHomeView(); // refresh UI
    }


