    private void showConnectionCodeInput()
    {
        mainPanel.removeAll();

        JPanel container = new JPanel(new BorderLayout());

        // -----------------------------
        // STACKED TOP PANEL: Title + Code + Base URL
        // -----------------------------
        JPanel topPanel = new JPanel();
        topPanel.setLayout(new BoxLayout(topPanel, BoxLayout.Y_AXIS));

        // BaseURL input
        JTextField baseUrlField = new JTextField();
        baseUrlField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 25));

        // Title
        JLabel title = new JLabel("Enter " + CODE_LENGTH + "-Digit Connection Code", SwingConstants.CENTER);
        title.setAlignmentX(Component.CENTER_ALIGNMENT);
        topPanel.add(title);

        topPanel.add(Box.createVerticalStrut(10)); // spacing

        // Code input fields
        JPanel codePanel = new JPanel(new GridLayout(1, CODE_LENGTH, 5, 0));
        JTextField[] fields = new JTextField[CODE_LENGTH];

        JButton submitButton = new JButton("Submit");
        submitButton.setEnabled(false);

        // Completion checker
        Runnable updateSubmitState = () ->
        {
            for (JTextField field : fields)
            {
                if (field == null || field.getText().isEmpty() || baseUrlField.getText().trim().isEmpty())
                {
                    submitButton.setEnabled(false);
                    return;
                }
            }
            submitButton.setEnabled(true);
        };

        baseUrlField.getDocument().addDocumentListener(new javax.swing.event.DocumentListener()
        {
            @Override
            public void insertUpdate(javax.swing.event.DocumentEvent e)
            {
                updateSubmitState.run();
            }

            @Override
            public void removeUpdate(javax.swing.event.DocumentEvent e)
            {
                updateSubmitState.run();
            }

            @Override
            public void changedUpdate(javax.swing.event.DocumentEvent e)
            {
                updateSubmitState.run();
            }
        });

        for (int i = 0; i < CODE_LENGTH; i++)
        {
            JTextField field = new JTextField();
            field.setHorizontalAlignment(JTextField.CENTER);
            field.setPreferredSize(new Dimension(40, 40));

            final int index = i;

            field.addKeyListener(new java.awt.event.KeyAdapter()
            {
                @Override
                public void keyTyped(java.awt.event.KeyEvent e)
                {
                    char c = e.getKeyChar();
                    if (!Character.isDigit(c))
                    {
                        e.consume();
                        return;
                    }

                    field.setText(String.valueOf(c));
                    e.consume();

                    if (index < CODE_LENGTH - 1)
                    {
                        fields[index + 1].requestFocus();
                    }

                    updateSubmitState.run();
                }

                @Override
                public void keyPressed(java.awt.event.KeyEvent e)
                {
                    if (e.getKeyCode() == java.awt.event.KeyEvent.VK_BACK_SPACE)
                    {
                        if (field.getText().isEmpty() && index > 0)
                        {
                            fields[index - 1].setText("");
                            fields[index - 1].requestFocus();
                        }
                        else
                        {
                            field.setText("");
                        }

                        updateSubmitState.run();
                        e.consume();
                    }
                }
            });

            // Paste handling
            field.setTransferHandler(new TransferHandler()
            {
                @Override
                public boolean importData(TransferSupport support)
                {
                    try
                    {
                        String data = (String) support.getTransferable()
                                .getTransferData(java.awt.datatransfer.DataFlavor.stringFlavor);

                        data = data.replaceAll("\\D", "");
                        if (data.isEmpty()) return false;

                        for (int j = 0; j < CODE_LENGTH; j++)
                        {
                            if (j < data.length())
                                fields[j].setText(String.valueOf(data.charAt(j)));
                            else
                                fields[j].setText("");
                        }

                        if (data.length() >= CODE_LENGTH)
                            fields[CODE_LENGTH - 1].requestFocus();
                        else
                            fields[data.length()].requestFocus();

                        updateSubmitState.run();
                        return true;
                    }
                    catch (Exception ex)
                    {
                        return false;
                    }
                }
            });

            fields[i] = field;
            codePanel.add(field);
        }

        codePanel.setAlignmentX(Component.CENTER_ALIGNMENT);
        topPanel.add(codePanel);

        topPanel.add(Box.createVerticalStrut(15)); // spacing

        // Endpoint URL label + helper text + input
        JLabel urlLabel = new JLabel("Endpoint URL");
        urlLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        topPanel.add(urlLabel);

        JLabel urlHelpLabel = new JLabel("Home Assistant or any compatible endpoint");
        urlHelpLabel.setFont(FontManager.getRunescapeSmallFont());
        urlHelpLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        urlHelpLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        topPanel.add(urlHelpLabel);
        topPanel.add(Box.createVerticalStrut(3));

        topPanel.add(baseUrlField);

        container.add(topPanel, BorderLayout.CENTER);

        // -----------------------------
        // Bottom buttons: Back + Submit
        // -----------------------------

        JPanel buttonContainer = new JPanel();
        buttonContainer.setLayout(new BoxLayout(buttonContainer, BoxLayout.Y_AXIS));

        // Add spacing between Base URL and buttons
        buttonContainer.add(Box.createVerticalStrut(5));

        JButton backButton = new JButton("Back");
        backButton.addActionListener(e -> showHomeView());

        submitButton.addActionListener(e ->
        {
            String baseUrl = normalizeBaseUrl(baseUrlField.getText().trim());

            StringBuilder code = new StringBuilder();
            for (JTextField field : fields)
            {
                code.append(field.getText());
            }

            submitButton.setEnabled(false); // prevent double click

            homeAssistUtils.getToken(baseUrl, code.toString(), new TokenCallback()
            {
                @Override
                public void onSuccess(String token, String name)
                {
                    SwingUtilities.invokeLater(() ->
                    {
                        handleSuccessfulConnection(baseUrl, token, name);
                        submitButton.setEnabled(true);
                    });
                }

                @Override
                public void onFailure(Exception e)
                {
                    SwingUtilities.invokeLater(() ->
                    {
                        submitButton.setEnabled(true);
                        JOptionPane.showMessageDialog(
                                HAExporterPanel.this,
                                buildPairingFailureMessage(e),
                                "Failure",
                                JOptionPane.ERROR_MESSAGE
                        );
                    });
                }
            });
        });


        JPanel buttonPanel = new JPanel(new GridLayout(1, 2, 5, 5));
        buttonPanel.add(backButton);
        buttonPanel.add(submitButton);

        buttonContainer.add(buttonPanel);

        container.add(buttonContainer, BorderLayout.SOUTH);

        mainPanel.add(container, BorderLayout.CENTER);

        fields[0].requestFocus();
        revalidate();
        repaint();
    }

    private void handleSuccessfulConnection(String baseUrl, String token, String name)
    {
        configUtils.addStoredConnection(baseUrl, token, name);

        JOptionPane.showMessageDialog(
                this,
                "Connection saved!",
                "Success",
                JOptionPane.INFORMATION_MESSAGE
        );

        showHomeView();
    }

    private static String buildPairingFailureMessage(Exception e)
    {
        // Prefer the endpoint's own (sanitized) explanation, e.g. "Code expired"
        if (e instanceof PairingException && ((PairingException) e).getServerMessage() != null)
        {
            return ((PairingException) e).getServerMessage();
        }

        return "Connection failed, try again.\n" + e.getMessage();
    }

    private JCheckBox createCheckbox(String label, boolean selected, boolean globallyEnabled) {
        JCheckBox checkBox = new JCheckBox(
                globallyEnabled ? label : label + " (Globally disabled)",
                globallyEnabled && selected
        );

        checkBox.setEnabled(globallyEnabled);

        if (!globallyEnabled) {
            checkBox.setToolTipText("Turned off in the HA Exporter config tab");
        }

        checkBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        return checkBox;
    }

    private static ImageIcon loadIcon(String name)
    {
        return new ImageIcon(ImageUtil.loadImageResource(HAExporterPanel.class, "/icons/" + name + ".png"));
    }

    private static String normalizeBaseUrl(String url)
    {
        return url.trim().replaceAll("/+$", "");
    }
}

package haexporterplugin;

import com.google.inject.Provides;
import javax.inject.Inject;

import haexporterplugin.data.ActivePrayers;
import haexporterplugin.data.HealthData;
import haexporterplugin.data.PrayerData;
import haexporterplugin.data.SpellbookData;
import haexporterplugin.notifiers.*;
import haexporterplugin.utils.EasterEggUtils;
import haexporterplugin.utils.HomeAssistUtils;
import haexporterplugin.utils.MessageBuilder;
import haexporterplugin.utils.PrayerUtils;
import haexporterplugin.utils.TickUtils;
import haexporterplugin.utils.Utils;
import haexporterplugin.utils.WorldUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.*;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "HA Exporter",
	description = "Export Game data to your HomeAssistant"
)
public class HAExporterPlugin extends Plugin
{
	// Sent to endpoints as X-Osrs-Exporter-Version. Must match `version` in build.gradle (checked by PluginVersionTest).
	public static final String PLUGIN_VERSION = "1.6.2";

	@Inject
	private Client client;

	@Inject
	private HAExporterConfig config;

	@Inject
	private MessageBuilder messageBuilder;

	@Inject
	private ClientToolbar clientToolbar;

    private NavigationButton navButton;
	private @Inject TickUtils tickUtils;
	private @Inject AchievementDiaryNotifier achievementDiaryNotifier;
	private @Inject CombatTaskNotifier combatTaskNotifier;
	private @Inject SuperiorNotifier superiorNotifier;
	private @Inject LevelNotifier levelNotifier;
	private @Inject ItemNotifier itemNotifier;
	private @Inject LootNotifier lootNotifier;
	private @Inject LocationNotifier locationNotifier;
	private @Inject DeathNotifier deathNotifier;
	private @Inject CollectionNotifier collectionNotifier;
	private @Inject EasterEggUtils easterEggUtils;
	private @Inject HomeAssistUtils homeAssistUtils;
	private boolean initialized = false;

	@Override
	protected void startUp() throws Exception
	{
        HAExporterPanel panel = injector.getInstance(HAExporterPanel.class);
		navButton = NavigationButton.builder()
			.tooltip("HA Exporter")
			.icon(ImageUtil.loadImageResource(getClass(), "/ha-exporter-icon.png"))
			.priority(420)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		homeAssistUtils.startUp();
		panel.initialize();
		lootNotifier.init();

		easterEggUtils.init();

		log.debug("HA Exporter Started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		messageBuilder.addEvent("clientShutdown", "Disabled");
		tickUtils.sendNow();
		// Stop resending queued payloads; the "Disabled" message above is still attempted once
		homeAssistUtils.shutDown();
		locationNotifier.reset();
		easterEggUtils.shutDown();
		clientToolbar.removeNavigation(navButton);
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		if (!initialized) return;
		messageBuilder.addEvent("clientShutdown", "Shutdown");
		tickUtils.sendShutdown();
	}

	@Subscribe
	public void onAccountHashChanged(AccountHashChanged event)
	{
		// initialize() reads the hash itself, so only update once the player has been initialized
		if (!initialized) return;
		messageBuilder.setData("accounthash", Utils.accountHash(client.getAccountHash()));
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived playerLootReceived) {
		lootNotifier.onPlayerLootReceived(playerLootReceived);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		messageBuilder.setState(gameStateChanged.getGameState());
		levelNotifier.onGameStateChanged(gameStateChanged);
		collectionNotifier.onGameStateChanged(gameStateChanged);
		if (gameStateChanged.getGameState() == GameState.HOPPING)
		{
			initialized = false;
			locationNotifier.reset();
		}
		if (gameStateChanged.getGameState() == GameState.LOGIN_SCREEN)
		{
			messageBuilder.addEvent("clientShutdown", "Logout");
			tickUtils.sendNow();
			initialized = false;
			messageBuilder.resetData();
			locationNotifier.reset();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged statChanged)
	{
		var exp = statChanged.getSkill();

		if (statChanged.getSkill() == Skill.HITPOINTS){
			HealthData health = new HealthData(statChanged.getBoostedLevel(), client.getRealSkillLevel(Skill.HITPOINTS));
			messageBuilder.setData("health", health);
			if (config.sendHealthInstantly()) {
				tickUtils.sendNow();
			}
		}
		if (statChanged.getSkill() == Skill.PRAYER){
			PrayerData prayer = new PrayerData(statChanged.getBoostedLevel(), client.getRealSkillLevel(Skill.PRAYER));
			messageBuilder.setData("prayer", prayer);
			if (config.sendPrayerInstantly()) {
				tickUtils.sendNow();
			}
		}
	}

	@Subscribe(priority = 1) // run before the base loot tracker plugin
	public void onChatMessage(ChatMessage chatMessage) {
		String source = chatMessage.getName() != null && !chatMessage.getName().isEmpty() ? chatMessage.getName() : chatMessage.getSender();
		switch (chatMessage.getType()){
			case GAMEMESSAGE:
				if ("runelite".equals(source)) {
					// filter out plugin-sourced chat messages
					return;
				}
				lootNotifier.onGameMessage(chatMessage.getMessage());
				deathNotifier.onGameMessage(chatMessage.getMessage());
				combatTaskNotifier.onChatMessage(chatMessage);
				achievementDiaryNotifier.onChatMessage(chatMessage);
				superiorNotifier.onChatMessage(chatMessage);
				collectionNotifier.onChatMessage(chatMessage);
				break;
		}

	}

	@Subscribe(priority = 1) // run before the base loot tracker plugin
	public void onServerNpcLoot(ServerNpcLoot serverNpcLoot) {
		// temporarily only use new event when needed
		int npcId = serverNpcLoot.getComposition().getId();
		var name = serverNpcLoot.getComposition().getName();
		if (npcId != NpcID.YAMA && npcId != NpcID.HESPORI && !name.startsWith("Hallowed Sepulchre")) {
			return;
		}

		lootNotifier.onServerNpcLoot(serverNpcLoot);
	}

	@Subscribe(priority = 1) // run before the base loot tracker plugin
	public void onNpcLootReceived(NpcLootReceived npcLootReceived) {
		if (npcLootReceived.getNpc().getId() == NpcID.YAMA) {
			// handled by ServerNpcLoot, but return just in case
			return;
		}

		lootNotifier.onNpcLootReceived(npcLootReceived);
	}

	@Subscribe
	public void onLootReceived(LootReceived lootReceived) {
		lootNotifier.onLootReceived(lootReceived);
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		deathNotifier.onScript(event);
		collectionNotifier.onScript(event);
	}

	@Subscribe
	public void onActorDeath(ActorDeath actor) {
		deathNotifier.onActorDeath(actor);
		if (client.getLocalPlayer() == actor.getActor()){
			easterEggUtils.playGarbage();
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event) {
		deathNotifier.onInteraction(event);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned npcSpawned) {
		superiorNotifier.onNpcSpawned(npcSpawned);
	}

	@Subscribe
	public void onGameTick(GameTick gameTick){
		tickUtils.onTick();

		updateSpellbook();
		updateActivePrayers();

		levelNotifier.onTick();
		itemNotifier.onTick();
		locationNotifier.onTick();
		superiorNotifier.onGameTick();

		if (!initialized){
			initialize();
		}

		tickUtils.sendOnSendRate();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		messageBuilder.setTickDelay(config.sendRate());
		lootNotifier.onConfigChanged(event.getKey(), event.getNewValue());
	}

	@Provides
	HAExporterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HAExporterConfig.class);
	}

	private void initialize(){
		if (client.getLocalPlayer() != null){
			String name = client.getLocalPlayer().getName();

			messageBuilder.setData("world", String.valueOf(client.getWorld()));
			messageBuilder.setData("worldtypes", WorldUtils.getWorldTypeNames(client.getWorldType()));
			int accountType = client.getVarbitValue(VarbitID.IRONMAN);
			messageBuilder.setData("accounttype", String.valueOf(accountType));
            assert name != null;
            messageBuilder.setData("name", name);
			messageBuilder.setData("accounthash", Utils.accountHash(client.getAccountHash()));

			// Get and set Health & Prayer
			HealthData health = new HealthData(client.getBoostedSkillLevel(Skill.HITPOINTS), client.getRealSkillLevel(Skill.HITPOINTS));
			PrayerData prayer = new PrayerData(client.getBoostedSkillLevel(Skill.PRAYER), client.getRealSkillLevel(Skill.PRAYER));
			messageBuilder.setData("health", health);
			messageBuilder.setData("prayer", prayer);
			messageBuilder.setTickDelay(config.sendRate());

			tickUtils.sendNow();

			initialized = true;
		}
	}

	private void updateSpellbook(){
		int spellbookId = client.getVarbitValue(VarbitID.SPELLBOOK);
		SpellbookData spellbook = new SpellbookData(spellbookId);
		messageBuilder.setData("spellbook", spellbook);
	}

	private void updateActivePrayers(){
		ActivePrayers activePrayers = new ActivePrayers(PrayerUtils.getActivePrayers(client));
		messageBuilder.setData("activePrayers", activePrayers);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (event.getMenuOption().equals("Eat") && (event.getItemId() == ItemID.KEBAB || event.getItemId() == ItemID.UGTHANKI_KEBAB || event.getItemId() == ItemID.SUPER_KEBAB || event.getItemId() == ItemID.VARLAMORIAN_KEBAB)) {
			easterEggUtils.playKebab();
		}
	}
}

