package haexporterplugin.notifiers;

import com.google.common.annotations.VisibleForTesting;
import haexporterplugin.data.CollectionData;
import haexporterplugin.utils.KillCountTracker;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.ItemComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

import javax.annotation.Nullable;
import javax.inject.Inject;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
public class CollectionNotifier extends BaseNotifier {

    private @Inject ItemManager itemManager;
    private @Inject ClientThread clientThread;
    private @Inject KillCountTracker killCountTracker;

    private static final String COLLECTION_LOG_TITLE = "Collection log";
    private static final String NEW_ITEM_PREFIX = "New item:";

    // Value of the in-game "Collection log - New addition notification" setting that only uses chat (no popup)
    private static final int NEW_ITEM_NOTIFICATION_CHAT_ONLY = 1;

    // Item definitions scanned per client tick while building the name lookup
    private static final int ITEM_LOOKUP_BATCH_SIZE = 2000;

    private static final Pattern COLLECTION_LOG_PATTERN = Pattern.compile(
            "New item added to your collection log: (?<itemName>.+)"
    );

    private static final Pattern KILL_COUNT_PATTERN = Pattern.compile(
            "Your (?<key>.+) (?:kill|success|harvest|lap|completion) count is: (?<value>[\\d,]+)\\b"
    );

    private static final Pattern KILL_COUNT_PATTERN_SECONDARY = Pattern.compile(
            "Your (?:completed )?(?<key>.+?) count is: (?<value>[\\d,]+)\\b"
    );

    // Lowercase item name -> canonical item id, built in batches after login.
    private Map<String, Integer> itemIdByName = null;
    private Map<String, Integer> partialItemIdByName = null;
    private int nextItemId = 0;

    private boolean notificationStarted = false;

    public void onGameStateChanged(GameStateChanged event) {
        switch (event.getGameState()) {
            case LOGGED_IN:
                startItemNameLookup();
                break;
            case HOPPING:
            case LOGIN_SCREEN:
                killCountTracker.reset();
                break;
        }
    }

    // Popup mode: the collection log popup is driven by the same client scripts that draw the on-screen notification.
    public void onScript(ScriptPreFired event) {
        switch (event.getScriptId()) {
            case ScriptID.NOTIFICATION_START:
                notificationStarted = true;
                break;
            case ScriptID.NOTIFICATION_DELAY:
                if (!notificationStarted) return;
                notificationStarted = false;

                String itemName = parsePopupItemName(
                        client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE),
                        client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN));
                if (itemName != null) {
                    clientThread.invokeAtTickEnd(() -> handleCollectionLog(itemName));
                }
                break;
        }
    }

    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

        String message = Text.removeTags(event.getMessage());
        Integer killCount = parseKillCount(message);
        if (killCount != null) {
            killCountTracker.onKillCount(killCount, client.getTickCount());
            return;
        }

        // Chat-only mode shows no popup, so the chat message is the only signal; otherwise the popup is used,
        // which keeps an item from being reported twice
        if (client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != NEW_ITEM_NOTIFICATION_CHAT_ONLY) return;

        Matcher matcher = COLLECTION_LOG_PATTERN.matcher(message);
        if (matcher.matches()) {
            String itemName = matcher.group("itemName").trim();
            // At tick end, so a kill count or loot from the same tick is seen first
            clientThread.invokeAtTickEnd(() -> handleCollectionLog(itemName));
        }
    }

    /**
     * @return the item name from a "Collection log" popup, or null for any other popup
     */
    @Nullable
    @VisibleForTesting
    static String parsePopupItemName(@Nullable String title, @Nullable String body) {
        if (!COLLECTION_LOG_TITLE.equalsIgnoreCase(title) || body == null) return null;

        String text = Text.removeTags(body);
        if (!text.startsWith(NEW_ITEM_PREFIX)) return null;

        String itemName = text.substring(NEW_ITEM_PREFIX.length()).trim();
        return itemName.isEmpty() ? null : itemName;
    }

    @Nullable
    @VisibleForTesting
    static Integer parseKillCount(String message) {
        Matcher matcher = KILL_COUNT_PATTERN.matcher(message);
        if (!matcher.find()) {
            matcher = KILL_COUNT_PATTERN_SECONDARY.matcher(message);
            if (!matcher.find()) return null;
        }
        try {
            return Integer.parseInt(matcher.group("value").replace(",", ""));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private void handleCollectionLog(String itemName) {
        int itemId = resolveItemId(itemName);
        long value = itemId > 0 ? itemManager.getItemPrice(itemId) : 0L;

        // Items without a price (pets, untradeables, unresolved names) are always sent.
        if (value > 0 && value < config.clogMinValue()) {
            log.debug("Skipping collection log item below minimum value: {} ({} gp)", itemName, value);
            return;
        }

        Integer killCount = killCountTracker.getKillCount(client.getTickCount());

        log.debug("Collection log item obtained: {} (id: {}, value: {}, kc: {})", itemName, itemId, value, killCount);

        messageBuilder.addEvent("collectionLog", new CollectionData(itemName, itemId, value, killCount));
        tickUtils.sendNow();
    }

    private int resolveItemId(String itemName) {
        // Normally already built after login; finish it now if an item shows up before that
        while (!buildItemNameLookupBatch()) {
            // keep scanning
        }
        return itemIdByName.getOrDefault(itemName.toLowerCase(), -1);
    }

    // Scanning every item definition at once stalls the client, so it's spread over client ticks
    private void startItemNameLookup() {
        if (itemIdByName != null || partialItemIdByName != null) return;
        clientThread.invokeLater(this::buildItemNameLookupBatch);
    }

    /**
     * @return true once the lookup is complete
     */
    private boolean buildItemNameLookupBatch() {
        if (itemIdByName != null) return true;
        if (partialItemIdByName == null) {
            partialItemIdByName = new HashMap<>();
            nextItemId = 0;
        }

        int count = client.getItemCount();
        int end = Math.min(count, nextItemId + ITEM_LOOKUP_BATCH_SIZE);
        for (int id = nextItemId; id < end; id++) {
            int canonical = itemManager.canonicalize(id);
            if (canonical != id) continue;

            ItemComposition composition = itemManager.getItemComposition(canonical);
            if (composition.getNote() != -1 || composition.getPlaceholderTemplateId() != -1) continue;

            String name = composition.getName();
            if (name == null || name.isEmpty() || "null".equals(name)) continue;

            partialItemIdByName.putIfAbsent(name.toLowerCase(), canonical);
        }
        nextItemId = end;
        if (end < count) return false;

        itemIdByName = partialItemIdByName;
        partialItemIdByName = null;
        return true;
    }
}

package haexporterplugin.notifiers;

import haexporterplugin.enums.CombatTaskTier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.util.Text;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
public class CombatTaskNotifier extends BaseNotifier {

    private static final Pattern COMBAT_TASK_PATTERN = Pattern.compile(
            "Congratulations, you've completed an? (?<tier>easy|medium|hard|elite|master|grandmaster) combat task:(?<task>.+?)",
            Pattern.CASE_INSENSITIVE
    );

    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

        String msg = Text.removeTags(event.getMessage());
        Matcher matcher = COMBAT_TASK_PATTERN.matcher(msg);

        if (matcher.matches()) {
            String task = matcher.group("task");
            String tier = matcher.group("tier");

            CombatTaskTier parsedTier = CombatTaskTier.fromString(tier);
            if (parsedTier != null && parsedTier.compareTo(config.combatTaskMinTier()) < 0) {
                log.debug("Skipping combat task below minimum tier: {} (tier: {})", task, tier);
                return;
            }

            log.debug("Detected combat task completion: {} (tier: {})", task, tier);

            Map<String, Object> thisEvent = new HashMap<>();
            thisEvent.put("taskName", task);
            thisEvent.put("tier", tier);
            messageBuilder.addEvent("combatTask", thisEvent);
        }
    }

}

package haexporterplugin.notifiers;

import com.google.common.annotations.VisibleForTesting;
import haexporterplugin.data.ItemData;
import haexporterplugin.enums.AccountType;
import haexporterplugin.enums.Danger;
import haexporterplugin.enums.ExceptionalDeath;
import haexporterplugin.events.DeathEvent;
import haexporterplugin.utils.ItemUtils;
import haexporterplugin.utils.Utils;
import haexporterplugin.utils.WorldUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ParamID;
import net.runelite.api.Player;
import net.runelite.api.SkullIcon;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.NPCManager;
import org.apache.commons.lang3.ArrayUtils;
import org.apache.commons.lang3.StringUtils;
import org.apache.commons.lang3.tuple.Pair;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.lang.ref.WeakReference;
import java.util.*;
import java.util.function.BiFunction;
import java.util.function.BiPredicate;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.stream.Collectors;

/**
 * Code based on DeathNotifier in Dink Plugin
 * source: <a href="https://github.com/pajlads/DinkPlugin/blob/master/src/main/java/dinkplugin/notifiers/DeathNotifier.java"></a>
 */

@Slf4j
@Singleton
public class DeathNotifier extends BaseNotifier {

    private static final String ATTACK_OPTION = "Attack";

    private static final String TOA_DEATH_MSG = "You failed to survive the Tombs of Amascut";

    private static final String TOB_DEATH_MSG = "Your party has failed";

    private static final String FORTIS_DOOM_MSG = "You have been doomed!";

    /**
     * @see <a href="https://github.com/Joshua-F/cs2-scripts/blob/master/scripts/%5Bclientscript,tob_hud_portal%5D.cs2">CS2 Reference</a>
     */
    private static final int TOB_HUB_PORTAL_SCRIPT = 2307;

    /**
     * Checks whether the actor is alive and interacting with the specified player.
     */
    private static final BiPredicate<Player, Actor> INTERACTING;

    /**
     * Checks whether a NPC is a valid candidate to be our killer.
     */
    private static final Predicate<NPCComposition> NPC_VALID;

    /**
     * Orders NPCs by their likelihood of being our killer.
     */
    private static final BiFunction<NPCManager, Player, Comparator<NPC>> NPC_COMPARATOR;

    /**
     * Orders actors by their likelihood of being the killer of the specified player.
     */
    private static final Function<Player, Comparator<Player>> PK_COMPARATOR;

    @Inject
    private ItemManager itemManager;

    @Inject
    private NPCManager npcManager;

    /**
     * Tracks the last {@link Actor} our local player interacted with,
     * for the purposes of attributing deaths to particular {@link Player}'s.
     * <p>
     * Note: this is wrapped in a weak reference to allow garbage collection,
     * for example if the {@link Actor} despawns.
     * As a result, the underlying reference can be null.
     *
     * @see #identifyKiller()
     */
    private WeakReference<Actor> lastTarget = new WeakReference<>(null);

    public void onActorDeath(ActorDeath actor) {
        boolean self = client.getLocalPlayer() == actor.getActor();

        if (self)
            handleNotify(null);

        if (self || actor.getActor() == lastTarget.get())
            lastTarget = new WeakReference<>(null);
    }

    public void onGameMessage(String message) {
        var player = client.getLocalPlayer();
        if (message.equals(FORTIS_DOOM_MSG) && player.getHealthRatio() > 0 && Objects.requireNonNull(WorldUtils.getLocation(client, player)).getRegionID() == WorldUtils.FORTIS_REGION) {
            handleNotify(Danger.DANGEROUS);
            return;
        }

        if (message.contains(TOA_DEATH_MSG)) {
            handleNotify(Danger.DANGEROUS);
        }
    }

    public void onScript(ScriptPreFired event) {
        if (event.getScriptId() == TOB_HUB_PORTAL_SCRIPT && event.getScriptEvent() != null) {
            Object[] args = event.getScriptEvent().getArguments();
            if (args != null && args.length > 1) {
                Object text = args[1];
                if (text instanceof String && ((String) text).contains(TOB_DEATH_MSG)) {
                    // https://oldschool.runescape.wiki/w/Theatre_of_Blood#Death_within_the_Theatre
                    handleNotify(Danger.DANGEROUS);
                }
            }
        }
    }

    public void onInteraction(InteractingChanged event) {
        if (event.getSource() == client.getLocalPlayer() && event.getTarget() != null && event.getTarget().getCombatLevel() > 0) {
            lastTarget = new WeakReference<>(event.getTarget());
        }
    }

    private void handleNotify(Danger dangerOverride) {
        int regionId = Objects.requireNonNull(WorldUtils.getLocation(client)).getRegionID();
        Danger danger = dangerOverride != null ? dangerOverride : WorldUtils.getDangerLevel(client, regionId, Set.of(ExceptionalDeath.values()));

        Collection<ItemData> items = ItemUtils.getInventoryItems(client, itemManager);
        // Slots are meaningless once stacks are split and merged into kept/lost lists
        items.forEach(item -> item.setInventorySlot(null));
        List<ItemData> itemsByPrice = getPricedItems(items);

        Pair<List<ItemData>, List<ItemData>> split;
        if (danger == Danger.DANGEROUS) {
            int keepCount = getKeepCount();
            split = splitItemsByKept(itemsByPrice, keepCount);
        } else {
            split = Pair.of(itemsByPrice, Collections.emptyList());
        }
        List<ItemData> keptItems = split.getLeft();
        List<ItemData> lostItems = split.getRight();

        long losePrice = ItemUtils.getStackGePrice(lostItems);

        Actor killer = identifyKiller();
        boolean npc = killer instanceof NPC;
        String killerName = killer != null ? StringUtils.defaultIfEmpty(killer.getName(), "?") : null;

        List<ItemData> lostStacks = getStacks(lostItems, true);
        List<ItemData> keptStacks = getStacks(keptItems, false);

        DeathEvent deathEvent = new DeathEvent(
                losePrice,
                danger,
                killerName,
                npc ? ((NPC) killer).getId() : null,
                keptStacks,
                lostStacks,
                client.getLocalPlayer().getWorldLocation()
        );

        messageBuilder.addEvent("death", deathEvent);
        tickUtils.sendNow();
    }

    /**
     * @return the number of items the player would keep on an unsafe death
     */
    private int getKeepCount() {
        if (Utils.getAccountType(client) == AccountType.ULTIMATE_IRONMAN)
            return 0;

        var skull = client.getLocalPlayer().getSkullIcon();
        int keepCount = skull == SkullIcon.NONE ? 3 : 0;
        if (client.getVarbitValue(VarbitID.PRAYER_PROTECTITEM) == 1)
            keepCount++;
        return keepCount;
    }

    /**
     * @return the inferred {@link Actor} who killed us, or null if not killed by an external source
     */
    @Nullable
    private Actor identifyKiller() {
        // must be in unsafe wildness or pvp world to be pk'd
        boolean pvpEnabled = !WorldUtils.isPvpSafeZone(client) &&
                (client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) > 0 || WorldUtils.isPvpWorld(client.getWorldType()));

        Player localPlayer = client.getLocalPlayer();
        Predicate<Actor> interacting = a -> INTERACTING.test(localPlayer, a);

        // O(1) fast path based on last outbound interaction
        Actor lastTarget = this.lastTarget.get();
        if (checkLastInteraction(localPlayer, lastTarget, pvpEnabled))
            return lastTarget;

        // find another player interacting with us (that is preferably not a friend or clan member)
        if (pvpEnabled) {
            Optional<? extends Player> pker = client.getTopLevelWorldView().players().stream()
                    .filter(interacting)
                    .min(PK_COMPARATOR.apply(localPlayer)); // O(n)
            if (pker.isPresent())
                return pker.get();
        }

        // otherwise search through NPCs interacting with us
        return client.getTopLevelWorldView().npcs().stream()
                .filter(interacting)
                .filter(npc -> NPC_VALID.test(npc.getTransformedComposition()))
                .min(NPC_COMPARATOR.apply(npcManager, localPlayer)) // O(n)
                .orElse(null);
    }

    /**
     * @param localPlayer {@link net.runelite.api.Client#getLocalPlayer()}
     * @param actor       the {@link Actor} that is a candidate killer from {@link #lastTarget}
     * @param pvpEnabled  whether a player could be our killer (e.g., in wilderness)
     * @return whether the specified actor is the likely killer of the local player
     */
    private static boolean checkLastInteraction(Player localPlayer, Actor actor, boolean pvpEnabled) {
        if (!INTERACTING.test(localPlayer, actor))
            return false;

        if (actor instanceof Player) {
            Player other = (Player) actor;
            return pvpEnabled
                    && !other.isClanMember()
                    && !other.isFriend()
                    && !other.isFriendsChatMember();
        }

        if (actor instanceof NPC) {
            NPC npcActor = (NPC) actor;
            NPCComposition npc = npcActor.getTransformedComposition();

            if (!NPC_VALID.test(npc)) return false;
            assert npc != null;

            return ArrayUtils.contains(npc.getActions(), ATTACK_OPTION);
        }

        log.warn("Encountered unknown type of Actor; was neither Player nor NPC!");
        return false;
    }

    /**
     * @param items       the items whose prices should be queried
     * @return pairs of the passed items to their price, sorted by most expensive unit price first
     */
    private static List<ItemData> getPricedItems(Collection<ItemData> items) {
        return items.stream()
                .sorted(Comparator.comparingLong(ItemData::getGePrice).reversed())
                .collect(Collectors.toList());
    }

    /**
     * Takes the complete list of items in the player's inventory and assigns them to separate lists,
     * depending on whether they would be kept or lost upon an unsafe death.
     *
     * @param itemsByPrice inventory items transformed by {@link #getPricedItems(Collection)}
     * @param keepCount    the number of items kept on death
     * @return the kept items on death (left) and lost items on death (right), in stable order, in separate lists
     */
    @VisibleForTesting
    static Pair<List<ItemData>, List<ItemData>> splitItemsByKept(List<ItemData> itemsByPrice, int keepCount) {
        List<ItemData> kept = new ArrayList<>();
        List<ItemData> lost = new ArrayList<>();

        int remainingKeeps = keepCount;

        for (ItemData item : itemsByPrice) {
            int id = item.getId();
            int quantity = item.getQuantity();

            // Bonds are always kept
            if (id == ItemID.OSRS_BOND
                    || id == ItemID.BOUGHT_OSRS_BOND
                    || id == ItemID.OSRS_BOND_UNTRADEABLE) {
                kept.add(item);
                continue;
            }

            boolean neverKept = ItemUtils.isItemNeverKeptOnDeath(id);

            if (neverKept || remainingKeeps <= 0) {
                lost.add(item);
                continue;
            }

            int toKeep = Math.min(quantity, remainingKeeps);
            int toLose = quantity - toKeep;

            if (toKeep > 0) {
                kept.add(new ItemData(item.getName(), id, item.getGePrice(), item.getHaPrice(), toKeep));
                remainingKeeps -= toKeep;
            }

            if (toLose > 0) {
                lost.add(new ItemData(item.getName(), id, item.getGePrice(), item.getHaPrice(), toLose));
            }
        }

        return Pair.of(kept, lost);
    }

    private static List<ItemData> getStacks(List<ItemData> items, boolean reduce) {
        if (!reduce) {
            // Preserve exact stacks
            return items.stream().map(ItemData::new).collect(Collectors.toList());
        }

        // Merge stacks with same ID
        Map<Integer, ItemData> merged = new LinkedHashMap<>();
        for (ItemData item : items) {
            merged.merge(item.getId(),
                    new ItemData(item), // copy
                    (existing, incoming) -> {
                        existing.setQuantity(existing.getQuantity() + incoming.getQuantity());
                        return existing;
                    });
        }

        return new ArrayList<>(merged.values());
    }

    static {
        INTERACTING = (localPlayer, a) -> a != null && a != localPlayer && !a.isDead() && a.getInteracting() == localPlayer;

        NPC_VALID = comp -> comp != null && comp.isInteractible() && !comp.isFollower() && comp.getCombatLevel() > 0;

        NPC_COMPARATOR = (npcManager, localPlayer) -> Comparator
                .comparing(
                        NPC::getTransformedComposition,
                        Comparator.nullsFirst(
                                Comparator
                                        .comparing(
                                                (NPCComposition comp) -> comp.getStringValue(ParamID.NPC_HP_NAME),
                                                Comparator.comparing(StringUtils::isNotEmpty) // prefer has name in hit points UI
                                        )
                                        .thenComparing(comp -> ArrayUtils.contains(comp.getActions(), ATTACK_OPTION)) // prefer explicitly attackable
                                        .thenComparingInt(NPCComposition::getCombatLevel) // prefer high level
                                        .thenComparingInt(NPCComposition::getSize) // prefer large
                                        .thenComparing(NPCComposition::isMinimapVisible) // prefer visible on minimap
                                        .thenComparing(
                                                // prefer high max health
                                                comp -> npcManager.getHealth(comp.getId()),
                                                Comparator.nullsFirst(Comparator.naturalOrder())
                                        )
                        )
                )
                .thenComparingInt(p -> -localPlayer.getLocalLocation().distanceTo(p.getLocalLocation())) // prefer nearby
                .reversed(); // for consistency with PK_COMPARATOR such that Stream#min should be used in #identifyKiller

        PK_COMPARATOR = localPlayer -> Comparator
                .comparing(Player::isClanMember) // prefer not in clan
                .thenComparing(Player::isFriend) // prefer not friend
                .thenComparing(Player::isFriendsChatMember) // prefer not fc
                .thenComparingInt(p -> Math.abs(localPlayer.getCombatLevel() - p.getCombatLevel())) // prefer similar level
                .thenComparingInt(p -> -p.getCombatLevel()) // prefer higher level for a given absolute level gap
                .thenComparing(p -> p.getOverheadIcon() == null) // prefer praying
                .thenComparing(p -> p.getTeam() == localPlayer.getTeam()) // prefer different team cape
                .thenComparingInt(p -> localPlayer.getLocalLocation().distanceTo(p.getLocalLocation())); // prefer nearby
    }
}

package haexporterplugin.notifiers;

import haexporterplugin.data.Equipment;
import haexporterplugin.data.Inventory;
import haexporterplugin.data.ItemData;
import haexporterplugin.utils.ItemUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import java.util.List;

@Slf4j
public class ItemNotifier extends BaseNotifier
{
    private @Inject Client client;
    private @Inject ItemManager itemManager;

    public void onTick(){
        updateInventory();
    }

    private void updateInventory(){
        try {
            // Get current inventory items
            List<ItemData> inventoryItems = ItemUtils.getInventoryItems(client, itemManager);
            List<ItemData> equipmentItems = ItemUtils.getEquippedItems(client, itemManager);

            // Update messageBuilder with new inventory and equipment
            messageBuilder.setData("inventory", new Inventory(inventoryItems));
            messageBuilder.setData("equipment", new Equipment(equipmentItems));
        } catch (Exception e) {
            log.error("Error updating inventory/equipment", e);
        }
    }

}

package haexporterplugin.notifiers;

import haexporterplugin.data.SkillInfo;
import haexporterplugin.data.Stats;
import haexporterplugin.events.LevelEvent;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Experience;
import net.runelite.api.GameState;

import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.events.GameStateChanged;

import javax.inject.Singleton;
import java.util.*;

import static net.runelite.api.Experience.MAX_REAL_LEVEL;

@Slf4j
@Singleton
public class LevelNotifier extends BaseNotifier {
    private static final Set<WorldType> SPECIAL_WORLDS = EnumSet.of(WorldType.PVP_ARENA, WorldType.QUEST_SPEEDRUNNING, WorldType.BETA_WORLD, WorldType.NOSAVE_MODE, WorldType.TOURNAMENT_WORLD, WorldType.DEADMAN, WorldType.SEASONAL);
    public static final int LEVEL_FOR_MAX_XP = Experience.MAX_VIRT_LEVEL + 1; // 127
    private static final int SKILL_COUNT = Skill.values().length;
    private static final String COMBAT_NAME = "Combat";
    private final Map<String, Integer> currentLevels = new HashMap<>();
    private final Map<String, Integer> previousLevels = new HashMap<>();
    private final Map<Skill, Integer> currentXp = new EnumMap<>(Skill.class);
    static final int INIT_GAME_TICKS = 1; // ~10s
    private Set<WorldType> specialWorldType = null;
    // Ticks since login or the last hop, while waiting to take the baseline
    private int ticksSinceReset = 0;

    private void updateSkillsFromGameState() {
        for (Skill skill : Skill.values()) {
            int xp = client.getSkillExperience(skill);
            int level = client.getRealSkillLevel(skill);
            if (level >= MAX_REAL_LEVEL) {
                level = getLevel(xp);
            }
            currentLevels.put(skill.getName(), level);
            currentXp.put(skill, xp);
        }
        currentLevels.put(COMBAT_NAME, calculateCombatLevel());
    }

    private void initLevels() {
        updateSkillsFromGameState();
        previousLevels.putAll(currentLevels);
        this.specialWorldType = getSpecialWorldTypes();
    }

    private int getLevel(int xp) {
        // treat 200M XP as level 127
        if (xp >= Experience.MAX_SKILL_XP)
            return LEVEL_FOR_MAX_XP;

        // log(n) operation to support virtual levels
        return Experience.getLevelForXp(xp);
    }

    private int calculateCombatLevel() {
        return Experience.getCombatLevel(
                getRealLevel(Skill.ATTACK),
                getRealLevel(Skill.STRENGTH),
                getRealLevel(Skill.DEFENCE),
                getRealLevel(Skill.HITPOINTS),
                getRealLevel(Skill.MAGIC),
                getRealLevel(Skill.RANGED),
                getRealLevel(Skill.PRAYER)
        );
    }

    private int getRealLevel(Skill skill) {
        Integer cachedLevel = currentLevels.get(skill.getName());
        return cachedLevel != null
                ? Math.min(cachedLevel, MAX_REAL_LEVEL)
                : client.getRealSkillLevel(skill);
    }

    private Set<WorldType> getSpecialWorldTypes() {
        var world = client.getWorldType().clone();
        world.retainAll(SPECIAL_WORLDS); // O(1)
        return world;
    }

    private List<LevelEvent> detectAndUpdateLevelChanges() {
        List<LevelEvent> changedLevels = new ArrayList<LevelEvent>();
        for (String skillName : currentLevels.keySet()) {
            int currentLevel = currentLevels.get(skillName);
            int previousLevel = previousLevels.getOrDefault(skillName, currentLevel);
            if (currentLevel != previousLevel) {
                previousLevels.put(skillName, currentLevel);
                if (shouldSend(skillName, currentLevel, config.levelMinValue(),
                        config.levelInterval(), config.levelIncludeVirtual(), config.levelIncludeCombat())) {
                    changedLevels.add(new LevelEvent(skillName, currentLevel));
                }
            }
        }
        return changedLevels;
    }

    static boolean shouldSend(String skillName, int level, int minLevel, int interval, boolean includeVirtual, boolean includeCombat) {
        boolean combat = COMBAT_NAME.equals(skillName);
        if (combat && !includeCombat) return false;
        if (!combat && level > MAX_REAL_LEVEL && !includeVirtual) return false;
        if (level < minLevel) return false;
        return level == MAX_REAL_LEVEL || level % Math.max(interval, 1) == 0;
    }

    private Stats buildStats() {
        Map<String, SkillInfo> skillsMap = new LinkedHashMap<>();
        for (Skill runeLiteSkill : Skill.values()) {
            String skillName = runeLiteSkill.getName();
            Integer xp = currentXp.get(runeLiteSkill);
            Integer level = currentLevels.get(skillName);
            if (xp != null && level != null) {
                skillsMap.put(skillName, new SkillInfo(xp, level));
            }
        }
        return new Stats(skillsMap);
    }

    public void onGameStateChanged(GameStateChanged event) {
        // A hop or re-login can switch to a character with different stats (e.g. a special world or another
        // account), so take a new baseline instead of reporting the difference as level-ups
        if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOGIN_SCREEN) {
            currentLevels.clear();
            previousLevels.clear();
            currentXp.clear();
            ticksSinceReset = 0;
        }
    }

    public void onTick(){
        // Give the client a moment after login or a hop to report the new character's stats
        if (previousLevels.isEmpty() && ++ticksSinceReset > INIT_GAME_TICKS) {
            initLevels();
            return;
        }

        updateSkillsFromGameState();
        List<LevelEvent> changedLevels = detectAndUpdateLevelChanges();

        Stats stats = buildStats();
        messageBuilder.setData("stats", stats);

        if (!changedLevels.isEmpty()) {
            messageBuilder.addEvent("levelUp", changedLevels);
            tickUtils.sendNow();
        }
    }
}

package haexporterplugin.notifiers;

import haexporterplugin.data.PlayerLocation;
import haexporterplugin.data.TrailPoint;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

@Slf4j
public class LocationNotifier extends BaseNotifier{
    // Where the player was on the previous tick; null until the first tick after a reset
    private WorldPoint previousPoint;
    private boolean previousOnBoat;

    public void onTick()
    {
        Actor player = client.getLocalPlayer();
        LocalPoint localPoint = player.getLocalLocation();
        WorldView worldView = player.getWorldView();
        int worldViewId = worldView.getId();
        boolean isOnBoat = worldViewId != WorldView.TOPLEVEL;
        WorldPoint worldPoint;
        if (isOnBoat) {
            WorldEntity worldEntity = client.getTopLevelWorldView().worldEntities().byIndex(worldViewId);
            worldPoint = WorldPoint.fromLocalInstance(client, worldEntity.getLocalLocation());
        } else {
            worldPoint = WorldPoint.fromLocalInstance(client, localPoint);
        }

        recordLocation(worldPoint, isOnBoat);
    }

    void recordLocation(WorldPoint worldPoint, boolean isOnBoat)
    {
        PlayerLocation playerLocation = new PlayerLocation(worldPoint, isOnBoat);

        messageBuilder.setData("location", playerLocation);

        if (!config.includeLocation()) {
            // Forget the previous tile, so the trail starts with the current one when sharing is switched back on
            reset();
            return;
        }

        WorldPoint previous = previousPoint;
        boolean wasOnBoat = previousOnBoat;
        previousPoint = worldPoint;
        previousOnBoat = isOnBoat;

        if (worldPoint.equals(previous) && isOnBoat == wasOnBoat) {
            return;
        }

        // Teleports aren't marked: receivers see two points that are far apart and decide for themselves
        messageBuilder.addLocationTrailPoint(new TrailPoint(worldPoint, isOnBoat, System.currentTimeMillis()));
    }

    // Called when the player logs out or hops, so the first tile afterwards is always recorded
    public void reset()
    {
        previousPoint = null;
        previousOnBoat = false;
    }
}

package haexporterplugin.notifiers;

import haexporterplugin.data.ItemData;
import haexporterplugin.data.LootData;
import haexporterplugin.data.RareItemData;
import haexporterplugin.enums.LootCriteria;
import haexporterplugin.utils.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

import javax.inject.Inject;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CopyOnWriteArraySet;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Slf4j
public class LootNotifier extends BaseNotifier{

    private @Inject ItemManager itemManager;
    private @Inject KillCountTracker killCountTracker;

    public LootData lastDrop = null;


    public static final String GAUNTLET_BOSS = "Crystalline Hunllef", THE_GAUNTLET = "The Gauntlet";
    public static final String CG_NAME = "Corrupted Gauntlet", CG_BOSS = "Corrupted Hunllef";
    public static final String TOA = "Tombs of Amascut";
    public static final String TOB = "Theatre of Blood";
    public static final String COX = "Chambers of Xeric";

    public static final Set<String> SPECIAL_LOOT_NPC_NAMES = Set.of("The Whisperer", "Araxxor",
            "Branda the Fire Queen", "Eldric the Ice King", GAUNTLET_BOSS, CG_BOSS);

    public void init() {
        itemNameAllowlist.clear();
        itemNameAllowlist.addAll(
                Utils.readDelimited(config.lootItemAllowlist())
                        .map(Utils::regexify)
                        .filter(Objects::nonNull)
                        .collect(Collectors.toList())
        );

        itemNameDenylist.clear();
        itemNameDenylist.addAll(
                Utils.readDelimited(config.lootItemDenylist())
                        .map(Utils::regexify)
                        .filter(Objects::nonNull)
                        .collect(Collectors.toList())
        );

        sourceDenylist.clear();
        sourceDenylist.addAll(
                Utils.readDelimited(config.lootSourceDenylist())
                        .map(String::toLowerCase)
                        .collect(Collectors.toList())
        );
    }

    private boolean matchesAnyPattern(Collection<Pattern> patterns, String itemName) {
        return patterns.stream().anyMatch(pattern -> pattern.matcher(itemName).matches());
    }

    public void onServerNpcLoot(ServerNpcLoot serverNpcLoot) {
        var comp = serverNpcLoot.getComposition();
        var items = ItemUtils.itemsToItemDataList(serverNpcLoot.getItems(), itemManager);
        this.handleNotify(items, comp.getName(), LootRecordType.NPC, comp.getId());
    }

    public void onNpcLootReceived(NpcLootReceived npcLootReceived) {

        NPC npc = npcLootReceived.getNpc();
        int id = npc.getId();

        var items = ItemUtils.itemsToItemDataList(npcLootReceived.getItems(), itemManager);
        this.handleNotify(items, npc.getName(), LootRecordType.NPC, id);
    }

    public void onPlayerLootReceived(PlayerLootReceived playerLootReceived) {
        if (!config.lootIncludePlayer() || WorldUtils.isSafeArea(client))
            return;
        var items = ItemUtils.itemsToItemDataList(playerLootReceived.getItems(), itemManager);
        handleNotify(items, playerLootReceived.getPlayer().getName(), LootRecordType.PLAYER, null);
    }

    public void onGameMessage(String message) {
        if ("You have found a Pharaoh's sceptre! It fell on the floor.".equals(message)) {
            var items = ItemUtils.itemStackToItemData(new ItemStack(ItemID.PHARAOHS_SCEPTRE, 1), itemManager);
            this.handleNotify(List.of(items), "Pyramid Plunder", LootRecordType.EVENT, null);
        }
    }

    public void onLootReceived(LootReceived lootReceived) {

        var items = ItemUtils.itemsToItemDataList(lootReceived.getItems(), itemManager);
        // only consider non-NPC and non-PK loot
        if (lootReceived.getType() == LootRecordType.EVENT || lootReceived.getType() == LootRecordType.PICKPOCKET) {
            if (lootReceived.getType() == LootRecordType.PICKPOCKET && !config.lootIncludePickpocket()) {
                return;
            }
            if ("Barbarian Assault high gamble".equals(lootReceived.getName())) {
                // skip ba gambles
                return;
            }

            String source = getStandardizedSource(lootReceived);
            this.handleNotify(items, source, lootReceived.getType(), null);
        } else if (lootReceived.getType() == LootRecordType.NPC && SPECIAL_LOOT_NPC_NAMES.contains(lootReceived.getName())) {
            // Special case: upstream fires LootReceived for certain NPCs, but not NpcLootReceived
            String source = getStandardizedSource(lootReceived);
            var type = THE_GAUNTLET.equals(source) || CG_NAME.equals(source) ? LootRecordType.EVENT : lootReceived.getType();
            this.handleNotify(items, source, type, null);
        }
    }

    private final Collection<Pattern> itemNameAllowlist = new CopyOnWriteArrayList<>();
    private final Collection<Pattern> itemNameDenylist = new CopyOnWriteArrayList<>();
    private final Collection<String> sourceDenylist = new CopyOnWriteArraySet<>();

    private void handleNotify(Collection<ItemData> items, String dropper, LootRecordType type, Integer npcId) {
        // Recorded before any filtering: collection log items use the kill count of the drop they came from
        killCountTracker.onDrop(client.getTickCount());

        if (type != LootRecordType.PLAYER && sourceDenylist.contains(dropper.toLowerCase())) {
            log.debug("Skipping loot notif for denied loot source: {} ({})", dropper, type);
            return;
        }

        final int minValue = config.minLootValue();

        Collection<ItemData> reduced = ItemUtils.reduceItemStack(items);
        List<ItemData> serializedItems = new ArrayList<>(reduced.size());

        long totalStackValue = 0;
        boolean sendMessage = false;
        boolean onAllowList = false;
        ItemData max = null;
        RareItemData rarest = null;

        final double rarityThreshold = config.lootRarityThreshold() > 0 ? 1.0 / config.lootRarityThreshold() : Double.NaN;
        final boolean intersection = config.lootRarityValueIntersection() && Double.isFinite(rarityThreshold);
        for (ItemData item : reduced) {
            long totalPrice = ItemUtils.getStackGePrice(item);

            OptionalDouble rarity;
            if (type == LootRecordType.NPC) {
                rarity = rarityUtils.getRarity(dropper, item.getId(), item.getQuantity());
            } else if (type == LootRecordType.PICKPOCKET) {
                rarity = thievingUtils.getRarity(dropper, item.getId(), item.getQuantity());
            } else {
                rarity = OptionalDouble.empty();
            }

            boolean shouldSend;
            var criteria = EnumSet.noneOf(LootCriteria.class);
            if (totalPrice >= minValue) {
                criteria.add(LootCriteria.VALUE);
            }
            if (MathUtils.lessThanOrEqual(rarity.orElse(1), rarityThreshold)) {
                criteria.add(LootCriteria.RARITY);
            }
            if (intersection) {
                shouldSend = criteria.contains(LootCriteria.VALUE) && (rarity.isEmpty() || criteria.contains(LootCriteria.RARITY));
            } else {
                shouldSend = criteria.contains(LootCriteria.VALUE) || criteria.contains(LootCriteria.RARITY);
            }

            boolean denied = matchesAnyPattern(itemNameDenylist, item.getName());
            if (denied) {
                shouldSend = false;
                criteria.add(LootCriteria.DENYLIST);
            } else {
                if (matchesAnyPattern(itemNameAllowlist, item.getName())) {
                    shouldSend = true;
                    onAllowList = true;
                    criteria.add(LootCriteria.ALLOWLIST);
                }
                if (max == null || totalPrice > ItemUtils.getStackGePrice(max)) {
                    max = item;
                }
            }

            if (shouldSend) {
                sendMessage = true;
            }

            if (rarity.isPresent()) {
                RareItemData rareItem = RareItemData.of(item, rarity.getAsDouble());
                serializedItems.add(rareItem);
                if (!denied && (rarest == null || rareItem.getRarity() < rarest.getRarity())) {
                    rarest = rareItem;
                }
            } else {
                serializedItems.add(item);
            }
            totalStackValue += totalPrice;
        }

        Evaluable sourceLink = type == LootRecordType.PLAYER
                ? ReplacementUtils.ofLink(dropper, config.playerLookupService().getPlayerUrl(dropper))
                : ReplacementUtils.ofWiki(dropper);

        if (sendMessage || onAllowList) {
            // Send regular loot notification (or allowlisted item)
            LootData lootData = new LootData(
                    serializedItems,
                    max,
                    totalStackValue,
                    sourceLink,
                    type,
                    npcId,
                    Collections.emptySet()
            );
            messageBuilder.addEvent("loot", lootData);
            tickUtils.sendNow();
        } else if (config.lootIncludePkChest() && totalStackValue >= minValue && max != null && "Loot Chest".equalsIgnoreCase(dropper)) {
            // Special case: PK loot keys should trigger notification if total value exceeds configured minimum even
            // if no single item itself would exceed the min value config
            LootData lootData = new LootData(
                    serializedItems,
                    max,
                    totalStackValue,
                    sourceLink,
                    type,
                    npcId,
                    Collections.emptySet()
            );
            messageBuilder.addEvent("pkLoot", lootData);
            tickUtils.sendNow();
        }
    }

    public String getStandardizedSource(LootReceived event) {
        if (GAUNTLET_BOSS.equals(event.getName())) {
            return THE_GAUNTLET;
        } else if (CG_BOSS.equals(event.getName())) {
            return CG_NAME;
        } else if (lastDrop != null && shouldUseChatName(event)) {
            return lastDrop.getSource().toString(); // distinguish entry/expert/challenge modes
        }
        return event.getName();
    }

    private boolean shouldUseChatName(LootReceived event) {
        assert lastDrop != null;
        if (event.getType() != LootRecordType.EVENT) return false;
        String lastSource = lastDrop.getSource().toString();
        Predicate<String> coincides = source -> source.equals(event.getName()) && lastSource.startsWith(source);
        return coincides.test(TOA) || coincides.test(TOB) || coincides.test(COX);
    }

    public void onConfigChanged(String key, String value) {
        if ("lootSourceDenylist".equals(key)) {
            sourceDenylist.clear();
            sourceDenylist.addAll(
                    Utils.readDelimited(value)
                    .map(String::toLowerCase)
                    .collect(Collectors.toList())
            );
            return;
        }

        Collection<Pattern> itemNames;
        if ("lootItemAllowlist".equals(key)) {
            itemNames = itemNameAllowlist;
        } else if ("lootItemDenylist".equals(key)) {
            itemNames = itemNameDenylist;
        } else {
            return;
        }

        itemNames.clear();
        itemNames.addAll(
                Utils.readDelimited(value)
                .map(Utils::regexify)
                .filter(Objects::nonNull)
                .collect(Collectors.toList())
        );
    }
}

package haexporterplugin.notifiers;

import haexporterplugin.events.SuperiorEvent;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.util.Text;

import java.util.ArrayList;
import java.util.List;

@Slf4j
public class SuperiorNotifier extends BaseNotifier {

    // Same signal RuneLite's own Slayer plugin uses; only appears at the real spawn moment.
    private static final String SUPERIOR_MESSAGE = "A superior foe has appeared...";

    private final List<NPC> spawnedThisTick = new ArrayList<>();
    private boolean superiorSeenThisTick = false;

    public void onNpcSpawned(NpcSpawned event) {
        spawnedThisTick.add(event.getNpc());
    }

    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;
        if (Text.removeTags(event.getMessage()).contains(SUPERIOR_MESSAGE)) {
            superiorSeenThisTick = true;
        }
    }

    // Resolved on tick end so the message and the spawn are both collected regardless of event order.
    public void onGameTick() {
        if (superiorSeenThisTick) {
            NPC superior = nearestSpawnToPlayer();
            if (superior != null) {
                log.debug("Detected superior spawn: {} (id: {})", superior.getName(), superior.getId());
                messageBuilder.addEvent("superiorSpawn",
                        new SuperiorEvent(superior.getName(), superior.getId(), superior.getWorldLocation()));
                tickUtils.sendNow();
            } else {
                log.debug("Superior foe message seen but no NPC spawned this tick");
            }
        }
        spawnedThisTick.clear();
        superiorSeenThisTick = false;
    }

    // Superiors spawn adjacent to the player, replacing the monster just killed.
    private NPC nearestSpawnToPlayer() {
        Player local = client.getLocalPlayer();
        if (local == null) return null;
        WorldPoint playerLocation = local.getWorldLocation();
        if (playerLocation == null) return null;

        NPC nearest = null;
        int bestDistance = Integer.MAX_VALUE;
        for (NPC npc : spawnedThisTick) {
            WorldPoint location = npc.getWorldLocation();
            if (location == null) continue;
            int distance = location.distanceTo(playerLocation);
            if (distance < bestDistance) {
                bestDistance = distance;
                nearest = npc;
            }
        }
        return nearest;
    }
}

package haexporterplugin.utils;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Setter;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.*;
import java.util.stream.Collectors;

@Slf4j
public abstract class AbstractRarityUtils {

    protected final Gson gson;
    protected final ItemManager itemManager;
    protected final Map<String, Collection<RareDrop>> dropsBySourceName;

    AbstractRarityUtils(String resourceName, int expectedSize, Gson gson, ItemManager itemManager) {
        this.gson = gson;
        this.itemManager = itemManager;
        this.dropsBySourceName = new HashMap<>(expectedSize);

        Map<String, List<RawDrop>> raw;
        try (InputStream is = getClass().getResourceAsStream(resourceName);
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is)))) {
            raw = gson.fromJson(reader, new TypeToken<Map<String, List<RawDrop>>>() {}.getType());
        } catch (Exception e) {
            log.error("Failed to read monster drop rates", e);
            return;
        }

        raw.forEach((sourceName, rawDrops) -> {
            ArrayList<RareDrop> drops = rawDrops.stream()
                    .map(RawDrop::transform)
                    .flatMap(Collection::stream)
                    .collect(Collectors.toCollection(ArrayList::new));
            drops.trimToSize();
            dropsBySourceName.put(sourceName, drops);
        });
    }

    public OptionalDouble getRarity(String sourceName, int itemId, int quantity) {
        ItemComposition composition = itemId >= 0 ? itemManager.getItemComposition(itemId) : null;
        int canonical = composition != null && composition.getNote() != -1 ? composition.getLinkedNoteId() : itemId;
        String itemName = composition != null ? composition.getMembersName() : "";
        Collection<Integer> variants = new HashSet<>(
                ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical))
        );
        return dropsBySourceName.getOrDefault(sourceName, Collections.emptyList())
                .stream()
                .filter(drop -> drop.getMinQuantity() <= quantity && quantity <= drop.getMaxQuantity())
                .filter(drop -> {
                    int id = drop.getItemId();
                    if (id == itemId) return true;
                    return variants.contains(id) && itemName.equals(itemManager.getItemComposition(id).getMembersName());
                })
                .mapToDouble(RareDrop::getProbability)
                .reduce(Double::sum);
    }

    @Value
    protected static class RareDrop {
        int itemId;
        int minQuantity;
        int maxQuantity;
        double probability;
    }

    @Data
    @Setter(AccessLevel.PRIVATE)
    private static class RawDrop {
        private @SerializedName("i") int itemId;
        private @SerializedName("r") Integer rolls;
        private @SerializedName("d") double denominator;
        private @SerializedName("q") Integer quantity;
        private @SerializedName("m") Integer quantMin;
        private @SerializedName("n") Integer quantMax;

        Collection<RareDrop> transform() {
            int rounds = rolls != null ? rolls : 1;
            int min = quantMin != null ? quantMin : quantity;
            int max = quantMax != null ? quantMax : quantity;
            double prob = 1 / denominator;

            if (rounds == 1) {
                return List.of(new RareDrop(itemId, min, max, prob));
            }
            List<RareDrop> drops = new ArrayList<>(rounds);
            for (int successCount = 1; successCount <= rounds; successCount++) {
                double density = MathUtils.binomialProbability(prob, rounds, successCount);
                drops.add(new RareDrop(itemId, min * successCount, max * successCount, density));
            }
            return drops;
        }
    }
}

package haexporterplugin.utils;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.data.HAConnection;
import lombok.extern.slf4j.Slf4j;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;

@Slf4j
@Singleton
public class ConfigUtils {
    private @Inject HAExporterConfig config;
    private @Inject Gson gson;

    public List<HAConnection> getStoredConnections()
    {
        Type listType = new TypeToken<List<HAConnection>>() {}.getType();

        try
        {
            List<HAConnection> connections =
                    gson.fromJson(config.homeassistantConnections(), listType);

            return connections != null ? connections : new ArrayList<>();
        }
        catch (Exception e)
        {
            return new ArrayList<>();
        }
    }

    public void addStoredConnection(String baseUrl, String token, @Nullable String friendlyName){
        Type listType = new TypeToken<List<HAConnection>>() {}.getType();

        List<HAConnection> connections;

        try
        {
            connections = gson.fromJson(config.homeassistantConnections(), listType);
            if (connections == null)
                connections = new ArrayList<>();
        }
        catch (Exception ex)
        {
            connections = new ArrayList<>();
        }

        HAConnection connection = new HAConnection(baseUrl, token);
        if (friendlyName != null)
            connection.setFriendlyName(friendlyName);

        connections.add(connection);
        config.setHomeassistantConnections(gson.toJson(connections));
    }

    public void saveConnections(List<HAConnection> connections)
    {
        config.setHomeassistantConnections(gson.toJson(connections));
    }
}

package haexporterplugin.utils;

import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;

/**
 * Per-connection delivery state: when sending is paused, how long the next backoff lasts, and which
 * payloads are waiting to be resent. Kept in memory only and safe to use from any thread.
 */
public class ConnectionBackoff {
    static final long INITIAL_BACKOFF_MS = TimeUnit.SECONDS.toMillis(30);
    static final long MAX_BACKOFF_MS = TimeUnit.MINUTES.toMillis(10);
    static final int MAX_QUEUED_PAYLOADS = 50;
    static final long MAX_QUEUE_AGE_MS = TimeUnit.MINUTES.toMillis(10);
    // How long a queued payload can still take in a later one, see getMergeCandidate
    static final long MERGE_WINDOW_MS = TimeUnit.MINUTES.toMillis(1);
    // Lower bound for Retry-After pauses, so "Retry-After: 0" can't cause a tight retry loop
    static final long MIN_RETRY_AFTER_MS = TimeUnit.SECONDS.toMillis(1);

    public enum Outcome {
        SUCCESS,      // 2xx
        UNAUTHORIZED, // 401: token revoked, disable the connection
        GONE,         // 410: endpoint no longer accepts data, disable the connection
        RETRY_AFTER,  // 429 / 503: pause as long as Retry-After asks, back off when it is missing
        BACKOFF,      // 404 and other 5xx: exponential backoff
        REJECTED      // anything else: drop the payload, no backoff
    }

    private static final class QueuedPayload {
        private final String payload;
        private final long enqueuedAt;

        private QueuedPayload(String payload, long enqueuedAt) {
            this.payload = payload;
            this.enqueuedAt = enqueuedAt;
        }
    }

    private static final class State {
        // 0 while healthy, otherwise the end of the current (or most recent) pause
        private long pausedUntil;
        private long nextBackoff = INITIAL_BACKOFF_MS;
        private final Deque<QueuedPayload> queue = new ArrayDeque<>();
        // Queued payload that is currently being resent, null when none
        private QueuedPayload inFlight;
    }

    private final LongSupplier clock;
    private final Map<String, State> states = new HashMap<>();

    public ConnectionBackoff() {
        this(System::currentTimeMillis);
    }

    public ConnectionBackoff(LongSupplier clock) {
        this.clock = clock;
    }

    public static Outcome classify(int statusCode) {
        if (statusCode >= 200 && statusCode < 300) {
            return Outcome.SUCCESS;
        }
        if (statusCode == 401) {
            return Outcome.UNAUTHORIZED;
        }
        if (statusCode == 410) {
            return Outcome.GONE;
        }
        if (statusCode == 429 || statusCode == 503) {
            return Outcome.RETRY_AFTER;
        }
        // A 404 says the endpoint isn't there (yet), not that it refused the payload: Home Assistant answers it
        // from the moment its web server is up until the integration has registered its endpoints. A payload
        // dropped there would be followed at once by the next queued one, which gets the same answer
        if (statusCode == 404 || (statusCode >= 500 && statusCode < 600)) {
            return Outcome.BACKOFF;
        }
        return Outcome.REJECTED;
    }

    /**
     * Parses a Retry-After header, either delta-seconds or an HTTP-date.
     *
     * @return the moment (epoch millis) to retry at, or null when missing or invalid
     */
    public static Long parseRetryAfter(String headerValue, long nowMillis) {
        if (headerValue == null || headerValue.trim().isEmpty()) {
            return null;
        }

        String value = headerValue.trim();
        if (value.chars().allMatch(c -> c >= '0' && c <= '9')) {
            try {
                return Math.addExact(nowMillis, Math.multiplyExact(Long.parseLong(value), 1000L));
            } catch (NumberFormatException | ArithmeticException e) {
                return null;
            }
        }

        try {
            return ZonedDateTime.parse(value, DateTimeFormatter.RFC_1123_DATE_TIME).toInstant().toEpochMilli();
        } catch (DateTimeParseException e) {
            return null;
        }
    }

    public synchronized boolean isPaused(String key) {
        return getPausedUntil(key) > 0;
    }

    /**
     * @return the end of the current pause in epoch millis, or 0 when not paused
     */
    public synchronized long getPausedUntil(String key) {
        State state = states.get(key);
        return state != null && state.pausedUntil > clock.getAsLong() ? state.pausedUntil : 0;
    }

    public synchronized int getQueuedCount(String key) {
        State state = states.get(key);
        if (state == null) {
            return 0;
        }
        prune(state);
        return state.queue.size();
    }

    public synchronized void recordSuccess(String key) {
        State state = states.get(key);
        if (state == null) {
            return;
        }
        state.pausedUntil = 0;
        state.nextBackoff = INITIAL_BACKOFF_MS;
        removeIfIdle(key, state);
    }

    /**
     * Pauses for the current backoff delay and doubles it for next time, up to {@link #MAX_BACKOFF_MS}.
     * A failure reported while already paused (a request that was in flight when the pause began) is ignored.
     *
     * @return true when this is the first failure since the last successful delivery
     */
    public synchronized boolean recordFailure(String key) {
        long now = clock.getAsLong();
        State state = states.computeIfAbsent(key, k -> new State());
        if (state.pausedUntil > now) {
            return false;
        }

        boolean firstFailure = state.pausedUntil == 0;
        state.pausedUntil = now + state.nextBackoff;
        state.nextBackoff = Math.min(state.nextBackoff * 2, MAX_BACKOFF_MS);
        return firstFailure;
    }

    /**
     * Pauses until the moment the server asked for, kept between {@link #MIN_RETRY_AFTER_MS} and
     * {@link #MAX_BACKOFF_MS} from now. Does not advance the exponential backoff.
     *
     * @return true when this is the first failure since the last successful delivery
     */
    public synchronized boolean recordRetryAfter(String key, long untilMillis) {
        long now = clock.getAsLong();
        State state = states.computeIfAbsent(key, k -> new State());
        boolean firstFailure = state.pausedUntil == 0;
        long until = Math.max(now + MIN_RETRY_AFTER_MS, Math.min(untilMillis, now + MAX_BACKOFF_MS));
        state.pausedUntil = Math.max(state.pausedUntil, until);
        return firstFailure;
    }

    /**
     * Queues a payload for resending, dropping the oldest ones beyond {@link #MAX_QUEUED_PAYLOADS}
     * and any older than {@link #MAX_QUEUE_AGE_MS}.
     */
    public synchronized void enqueue(String key, String payload) {
        State state = states.computeIfAbsent(key, k -> new State());
        prune(state);
        state.queue.addLast(new QueuedPayload(payload, clock.getAsLong()));
        while (state.queue.size() > MAX_QUEUED_PAYLOADS) {
            state.queue.removeFirst();
        }
    }

    /**
     * Merging two payloads means parsing them, which is too slow to do while holding this object's lock
     * (the game thread takes it on every send). So the caller reads the candidate here, merges without
     * the lock and hands the result to {@link #replaceNewest}.
     *
     * @return the newest queued payload when a payload queued now may be merged into it: it was queued less
     *         than {@link #MERGE_WINDOW_MS} ago and is not being resent. Otherwise null
     */
    public synchronized String getMergeCandidate(String key) {
        State state = states.get(key);
        if (state == null) {
            return null;
        }
        prune(state);
        QueuedPayload newest = state.queue.peekLast();
        return isMergeable(state, newest) ? newest.payload : null;
    }

    /**
     * Replaces the newest queued payload by {@code merged}, which keeps its place and age in the queue.
     *
     * @param candidate the payload {@link #getMergeCandidate} returned
     * @return false when the candidate is no longer the newest queued payload or can no longer be merged
     *         into; nothing has changed then and the caller queues its payload on its own
     */
    public synchronized boolean replaceNewest(String key, String candidate, String merged) {
        State state = states.get(key);
        if (state == null) {
            return false;
        }
        prune(state);
        QueuedPayload newest = state.queue.peekLast();
        // Compared by identity: it has to be the very payload the caller merged
        if (!isMergeable(state, newest) || newest.payload != candidate) {
            return false;
        }
        state.queue.removeLast();
        state.queue.addLast(new QueuedPayload(merged, newest.enqueuedAt));
        return true;
    }

    private boolean isMergeable(State state, QueuedPayload newest) {
        return newest != null && newest != state.inFlight && newest.enqueuedAt > clock.getAsLong() - MERGE_WINDOW_MS;
    }

    /**
     * Starts resending the oldest queued payload. Pair every non-null result with {@link #completeDrain}.
     *
     * @return the payload to send, or null when paused, nothing is queued or a resend is already in flight
     */
    public synchronized String beginDrain(String key) {
        State state = states.get(key);
        if (state == null || state.inFlight != null || state.pausedUntil > clock.getAsLong()) {
            return null;
        }
        prune(state);
        state.inFlight = state.queue.peekFirst();
        return state.inFlight != null ? state.inFlight.payload : null;
    }

    /**
     * Finishes the resend started by {@link #beginDrain}: a delivered payload is removed from the queue,
     * otherwise it stays at the head to be retried after the next pause.
     */
    public synchronized void completeDrain(String key, boolean delivered) {
        State state = states.get(key);
        if (state == null || state.inFlight == null) {
            return;
        }
        if (delivered) {
            // Removed by identity: it may have been pushed out of the queue while in flight
            state.queue.remove(state.inFlight);
        }
        state.inFlight = null;
        removeIfIdle(key, state);
    }

    public synchronized void clear(String key) {
        states.remove(key);
    }

    public synchronized void clearAll() {
        states.clear();
    }

    private void prune(State state) {
        long cutoff = clock.getAsLong() - MAX_QUEUE_AGE_MS;
        while (!state.queue.isEmpty() && state.queue.peekFirst().enqueuedAt < cutoff) {
            state.queue.removeFirst();
        }
    }

    private void removeIfIdle(String key, State state) {
        if (state.pausedUntil == 0 && state.inFlight == null && state.queue.isEmpty()) {
            states.remove(key);
        }
    }
}

package haexporterplugin.utils;

import haexporterplugin.HAExporterConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

import javax.inject.Inject;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@Slf4j
public class EasterEggUtils {
    @Inject
    private AudioPlayer audioPlayer;
    private @Inject HAExporterConfig config;

    public static ExecutorService executorService;

    public void init(){
        executorService = Executors.newSingleThreadExecutor();
    }

    public void shutDown() throws Exception
    {
        executorService.shutdown();
    }

    public void playKebab(){
        if (config.kebab())
            executorService.submit(() -> playSound("kebab"));
    }

    public void playGarbage(){
        if (config.garbage())
            executorService.submit(() -> playSound("garbage"));
    }

    private void playSound(String file)
    {
        String filename = String.format("/%s.wav", file);

        try
        {
            audioPlayer.play(this.getClass(), filename, 1);
        } catch (Exception e)
        {
            log.error(e.getMessage(), e);
        }
    }
}

