package haexporterplugin.utils;

import com.google.common.net.UrlEscapers;
import lombok.Value;
import lombok.experimental.UtilityClass;

@UtilityClass
public class ReplacementUtils {

    public Evaluable ofText(String text) {
        return new Text(text);
    }

    public Evaluable ofLink(String text, String link) {
        return link != null ? new TextWithLink(text, link) : ofText(text);
    }

    public Evaluable ofWiki(String text, String searchPhrase) {
        return ofLink(text, "https://oldschool.runescape.wiki/w/Special:Search?search=" + UrlEscapers.urlPathSegmentEscaper().escape(searchPhrase));
    }

    public Evaluable ofWiki(String phrase) {
        return ofWiki(phrase, phrase);
    }

    @Value
    private static class Text implements Evaluable {
        String text;

        @Override
        public String evaluate(boolean rich) {
            return text;
        }
    }

    @Value
    private static class TextWithLink implements Evaluable {
        String text;
        String link;

        @Override
        public String evaluate(boolean rich) {
            return rich ? String.format("[%s](%s)", text, link) : text;
        }
    }

}

package haexporterplugin.utils;

import com.google.gson.Gson;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.OptionalDouble;

@Singleton
public class ThievingUtils extends AbstractRarityUtils {

    @Inject
    ThievingUtils(Gson gson, ItemManager itemManager) {
        super("/thieving.json", 32, gson, itemManager);
    }

    @Override
    public OptionalDouble getRarity(String sourceName, int itemId, int quantity) {
        if (itemId == ItemID.BLOOD_SHARD) {
            // https://oldschool.runescape.wiki/w/Blood_shard#Item_sources
            return OptionalDouble.of(1.0 / 5000);
        }

        if (itemId == ItemID.PRIF_TELEPORT_SEED) {
            // https://oldschool.runescape.wiki/w/Enhanced_crystal_teleport_seed#Item_sources
            return OptionalDouble.of(1.0 / 1024);
        }

        return super.getRarity(sourceName, itemId, quantity);
    }

}

package haexporterplugin.utils;

import haexporterplugin.HAExporterConfig;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class TickUtils {
    @Getter
    private int tickCount = 0;

    @Inject
    private MessageBuilder messageBuilder;

    @Inject
    private HomeAssistUtils homeAssistUtils;

    @Inject
    private HAExporterConfig config;

    @Inject
    private Client client;

    public void onTick(){
        tickCount++;
    }

    public void sendOnSendRate(){
        if (tickCount >= config.sendRate()){
            tickCount = 0;
            send();
        }
    }

    public void sendNow(){
        tickCount = 0;
        send();
    }

    public void sendShutdown(){
        send();
    }

    // Events and the location trail are cleared as soon as they're serialized, so each is part of one message only.
    // HomeAssistUtils keeps that message for every connection it could not be delivered to
    private void send(){
        if (dropOnSpecialWorld()) return;
        String json = messageBuilder.build();
        messageBuilder.resetEvents();
        messageBuilder.resetLocationTrail();
        homeAssistUtils.sendMessage(json);
    }

    // Nothing is sent from special worlds unless the user opted in. Pending events and trail points are
    // dropped too, so they can't show up later in a message from a normal world.
    private boolean dropOnSpecialWorld(){
        if (config.sendSpecialWorldData() || !WorldUtils.isSpecialWorld(client.getWorldType())){
            return false;
        }
        messageBuilder.resetEvents();
        messageBuilder.resetLocationTrail();
        return true;
    }
}

package haexporterplugin.utils;

import com.google.common.hash.HashCode;
import haexporterplugin.enums.AccountType;
import lombok.experimental.UtilityClass;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import org.apache.commons.lang3.StringUtils;
import org.jetbrains.annotations.NotNull;

import javax.annotation.Nullable;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import java.util.stream.Stream;


@Slf4j
@UtilityClass
public class Utils {
    public AccountType getAccountType(Client client) {
        return AccountType.get(client.getVarbitValue(VarbitID.IRONMAN));
    }

    // DO NOT CHANGE: changing the salt changes every user's accountHash, so receivers would see every account as new.
    private final byte[] ACCOUNT_HASH_SALT = "HAExporter-AccountHash-v1".getBytes(StandardCharsets.UTF_8);

    /**
     * Same approach as Utils#dinkHash in Dink Plugin, but with our own salt.
     * source: <a href="https://github.com/pajlads/DinkPlugin/blob/master/src/main/java/dinkplugin/util/Utils.java"></a>
     *
     * @param accountHash the value of {@link Client#getAccountHash()}
     * @return a salted SHA-224 hex digest, or null when not logged in (-1) or SHA-224 is unavailable
     */
    @Nullable
    public String accountHash(long accountHash) {
        if (accountHash == -1) return null;

        MessageDigest digest;
        try {
            digest = MessageDigest.getInstance("SHA-224");
        } catch (NoSuchAlgorithmException e) {
            log.warn("Account hash could not be computed", e);
            return null;
        }

        byte[] input = ByteBuffer.allocate(8 + ACCOUNT_HASH_SALT.length)
                .putLong(accountHash)
                .put(ACCOUNT_HASH_SALT)
                .array();
        return HashCode.fromBytes(digest.digest(input)).toString();
    }

    private final Pattern DELIM = Pattern.compile("[,;\\n]");

    public Stream<String> readDelimited(String value) {
        if (value == null) return Stream.empty();
        return DELIM.splitAsStream(value)
                .map(String::trim)
                .filter(StringUtils::isNotEmpty);
    }

    /**
     * Converts simple patterns (asterisk is the only special character) into regexps.
     *
     * @param pattern a simple pattern (asterisks are wildcards, and the rest is a string literal)
     * @return a compiled regular expression associated with the simple pattern
     */
    @Nullable
    public Pattern regexify(@NotNull String pattern) {
        final int len = pattern.length();
        final StringBuilder sb = new StringBuilder(len + 2 + 4);
        int startIndex = 0;

        if (!pattern.startsWith("*")) {
            sb.append('^');
        } else {
            startIndex++;
        }

        int i;
        while ((i = pattern.indexOf('*', startIndex)) >= 0) {
            String section = pattern.substring(startIndex, i);
            sb.append(Pattern.quote(section));
            sb.append(".*");
            startIndex = i + 1;
        }

        if (startIndex < len) {
            sb.append(Pattern.quote(pattern.substring(startIndex)));
            sb.append('$');
        }

        try {
            return Pattern.compile(sb.toString(), Pattern.CASE_INSENSITIVE);
        } catch (PatternSyntaxException e) {
            log.warn("Failed to parse pattern: {}", pattern, e);
            return null;
        }
    }
}

package haexporterplugin.utils;

import com.google.common.collect.ImmutableSet;
import haexporterplugin.enums.AccountType;
import haexporterplugin.enums.Danger;
import haexporterplugin.enums.ExceptionalDeath;
import lombok.experimental.UtilityClass;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

import javax.annotation.Nullable;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;

@UtilityClass
public class WorldUtils {

    private final Set<WorldType> IGNORED_WORLDS = EnumSet.of(WorldType.PVP_ARENA, WorldType.QUEST_SPEEDRUNNING, WorldType.BETA_WORLD, WorldType.NOSAVE_MODE, WorldType.TOURNAMENT_WORLD);

    // Worlds that use separate or temporary characters (Leagues, Deadman, tournament, beta, …); same set as LevelNotifier
    private final Set<WorldType> SPECIAL_WORLDS = EnumSet.of(WorldType.PVP_ARENA, WorldType.QUEST_SPEEDRUNNING, WorldType.BETA_WORLD, WorldType.NOSAVE_MODE, WorldType.TOURNAMENT_WORLD, WorldType.DEADMAN, WorldType.SEASONAL);

    private final Set<Integer> BA_REGIONS = ImmutableSet.of(7508, 7509, 10322);
    private final Set<Integer> CASTLE_WARS_REGIONS = ImmutableSet.of(9520, 9620);
    private final Set<Integer> CLAN_WARS_REGIONS = ImmutableSet.of(12621, 12622, 12623, 13130, 13131, 13133, 13134, 13135, 13386, 13387, 13390, 13641, 13642, 13643, 13644, 13645, 13646, 13647, 13899, 13900, 14155, 14156);
    private final Set<Integer> COX_REGIONS = ImmutableSet.of(12889, 13136, 13137, 13138, 13139, 13140, 13141, 13145, 13393, 13394, 13395, 13396, 13397, 13401);
    private final Set<Integer> GALVEK_REGIONS = ImmutableSet.of(6486, 6487, 6488, 6489, 6742, 6743, 6744, 6745);
    private final Set<Integer> GAUNTLET_REGIONS = ImmutableSet.of(7512, 7768, 12127); // includes CG
    private final Set<Integer> LMS_REGIONS = ImmutableSet.of(13658, 13659, 13660, 13914, 13915, 13916, 13918, 13919, 13920, 14174, 14175, 14176, 14430, 14431, 14432);
    private final Set<Integer> POH_REGIONS = ImmutableSet.of(7257, 7513, 7514, 7769, 7770, 8025, 8026);
    private final Set<Integer> SOUL_REGIONS = ImmutableSet.of(8493, 8748, 8749, 9005);
    private final Set<Integer> TOA_REGIONS = ImmutableSet.of(14160, 14162, 14164, 14674, 14676, 15184, 15186, 15188, 15696, 15698, 15700);
    private final Set<Integer> TOB_REGIONS = ImmutableSet.of(12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125, 13379);
    private final Set<Integer> ZULRAH_REGIONS = Set.of(9007, 9008);
    private final int INFERNO_REGION = 9043;
    private final int CREATURE_GRAVEYARD_REGION = 13462;
    private final int NMZ_REGION = 9033;
    private final int TZHAAR_CAVE = 9551;
    public final int TZHAAR_PIT = 9552;
    public final int FORTIS_REGION = 7216;

    /**
     * @see <a href="https://chisel.weirdgloop.org/varbs/display?varbit=6104#ChangeFrequencyTitle">Chisel</a>
     */
    private final int DRAGON_SLAYER_II_COMPLETED = 215;

    @Nullable
    public static WorldPoint getLocation(Client client) {
        return getLocation(client, client.getLocalPlayer());
    }

    @Nullable
    public static WorldPoint getLocation(Client client, Actor actor) {
        if (actor == null)
            return null;

        WorldView wv = actor.getWorldView();
        if (wv.isInstance())
            return WorldPoint.fromLocalInstance(client, actor.getLocalLocation(), wv.getPlane());

        return actor.getWorldLocation();
    }

    public boolean isGridMaster(Client client) {
        if (client.getWorldType().contains(WorldType.TOURNAMENT_WORLD)) {
            return client.getVarbitValue(VarbitID.BINGO_INITIAL_SETUP_DONE) > 0;
        }
        return false;
    }

    public boolean isSeasonalDeadman(Set<WorldType> worldTypes) {
        return worldTypes.contains(WorldType.TOURNAMENT_WORLD) && worldTypes.contains(WorldType.DEADMAN);
    }

    public boolean isSeasonal(Client client) {
        EnumSet<WorldType> worldTypes = client.getWorldType();
        return worldTypes.contains(WorldType.SEASONAL) || isSeasonalDeadman(worldTypes) || isGridMaster(client);
    }

    /**
     * @return the names of the given world types in enum order, e.g. ["MEMBERS", "SEASONAL"]
     */
    public String[] getWorldTypeNames(Set<WorldType> worldTypes) {
        return worldTypes.stream()
                .sorted()
                .map(WorldType::name)
                .toArray(String[]::new);
    }

    public boolean isSpecialWorld(Set<WorldType> worldTypes) {
        return !Collections.disjoint(SPECIAL_WORLDS, worldTypes);
    }

    public boolean isIgnoredWorld(Set<WorldType> worldType) {
        return !Collections.disjoint(IGNORED_WORLDS, worldType);
    }

    public boolean isPvpWorld(Set<WorldType> worldType) {
        return worldType.contains(WorldType.PVP) || worldType.contains(WorldType.DEADMAN);
    }

    public boolean isPvpSafeZone(Client client) {
        Widget widget = client.getWidget(InterfaceID.PvpIcons.PVPW_SAFE);
        return widget != null && !widget.isHidden();
    }

    public boolean isBarbarianAssault(int regionId) {
        return BA_REGIONS.contains(regionId);
    }

    public boolean isCastleWars(int regionId) {
        return CASTLE_WARS_REGIONS.contains(regionId);
    }

    public boolean isChambersOfXeric(int regionId) {
        return COX_REGIONS.contains(regionId);
    }

    public boolean isClanWars(int regionId) {
        return CLAN_WARS_REGIONS.contains(regionId);
    }

    public boolean isGalvekRematch(Client client, int regionId) {
        return GALVEK_REGIONS.contains(regionId) && client.getVarbitValue(VarbitID.DS2) >= DRAGON_SLAYER_II_COMPLETED;
    }

    public boolean isGauntlet(int regionId) {
        return GAUNTLET_REGIONS.contains(regionId);
    }

    public boolean isInferno(Client client, int regionId) {
        return regionId == INFERNO_REGION && client.getVarpValue(VarPlayerID.SA_ENERGY_STORED) == 0;
    }

    /**
     * Checks whether the player is within TzHaar-Ket-Rak's Challenges
     * The in-game region is the same as the inferno, but a varp value is different
     */
    public boolean isJadChallenges(Client client, int regionId) {
        return regionId == INFERNO_REGION && client.getVarpValue(VarPlayerID.SA_ENERGY_STORED) > 0;
    }

    public boolean isLastManStanding(Client client) {
        if (LMS_REGIONS.contains(getLocation(client).getRegionID()))
            return true;

        Widget widget = client.getWidget(InterfaceID.BrOverlay.CONTENT);
        return widget != null && !widget.isHidden();
    }

    public boolean isMageTrainingArena(int regionId) {
        return regionId == CREATURE_GRAVEYARD_REGION;
    }

    public boolean isNightmareZone(int regionId) {
        return regionId == NMZ_REGION;
    }

    public boolean isPestControl(Client client) {
        Widget widget = client.getWidget(InterfaceID.PestStatusOverlay.PEST_STATUS_PORT2);
        return widget != null && !widget.isHidden();
    }

    public boolean isPlayerOwnedHouse(int regionId) {
        return POH_REGIONS.contains(regionId);
    }

    public boolean isSafeArea(Client client) {
        return getDangerLevel(client, getLocation(client).getRegionID(), Collections.emptySet()) == Danger.SAFE;
    }

    public boolean isSoulWars(int regionId) {
        return SOUL_REGIONS.contains(regionId);
    }

    public boolean isAmascutTombs(int regionId) {
        return TOA_REGIONS.contains(regionId);
    }

    public boolean isTheatreOfBlood(int regionId) {
        return TOB_REGIONS.contains(regionId);
    }

    public boolean isTzHaarFightCave(int regionId) {
        return regionId == TZHAAR_CAVE;
    }

    public boolean isTzHaarFightPit(int regionId) {
        return regionId == TZHAAR_PIT;
    }

    public boolean isZulrah(int regionId) {
        return ZULRAH_REGIONS.contains(regionId);
    }

    public Danger getDangerLevel(Client client, int regionId, Set<ExceptionalDeath> exceptions) {
        if (isGauntlet(regionId)) {
            // Players can't take items in or out of (Corrupted) Gauntlet, so these deaths are effectively safe
            // However: any Gauntlet death is still dangerous for hardcore (group) ironmen
            return checkException(Utils.getAccountType(client).isHardcore(), exceptions, ExceptionalDeath.GAUNTLET);
        }

        if (isAmascutTombs(regionId)) {
            // ToA is technically a dangerous activity, but multiple attempts can be permitted
            // the real TOA death is detected via game message in death notifier
            // However: any TOA death is still dangerous for hardcore (group) ironmen
            return checkException(Utils.getAccountType(client).isHardcore(), exceptions, ExceptionalDeath.TOA);
        }

        if (isTheatreOfBlood(regionId)) {
            // ToB is another dangerous activity, but the whole party needs to wipe for it to be a dangerous event
            // So we use HUD text to detect the real tob death in the notifier itself
            // However: any TOB death is still dangerous for hardcore (group) ironmen
            return checkException(Utils.getAccountType(client).isHardcore(), exceptions, ExceptionalDeath.TOB);
        }

        if (isChambersOfXeric(regionId)) {
            return checkException(Utils.getAccountType(client) == AccountType.HARDCORE_GROUP_IRONMAN, exceptions, ExceptionalDeath.COX);
        }

        if (isInferno(client, regionId)) {
            return checkException(Utils.getAccountType(client) == AccountType.HARDCORE_GROUP_IRONMAN, exceptions, ExceptionalDeath.INFERNO);
        }

        if (isJadChallenges(client, regionId)) {
            return checkException(Utils.getAccountType(client) == AccountType.HARDCORE_GROUP_IRONMAN, exceptions, ExceptionalDeath.JAD_CHALLENGES);
        }

        if (isTzHaarFightCave(regionId)) {
            if (Utils.getAccountType(client) == AccountType.HARDCORE_GROUP_IRONMAN) {
                return Danger.DANGEROUS;
            }
            if (exceptions.contains(ExceptionalDeath.FIGHT_CAVE)) {
                return Danger.EXCEPTIONAL;
            }
            if (client.getVarbitValue(VarbitID.KARAMJA_FIGHTCAVE_RESSURECTION) == 0 && exceptions.contains(ExceptionalDeath.DIARY_RESURRECTION) && client.getVarbitValue(VarbitID.KARAMJA_DIARY_ELITE_COMPLETE) > 0) {
                // Karamja Elite diary completion allows 1 free daily resurrection: https://github.com/pajlads/DinkPlugin/issues/548
                return Danger.EXCEPTIONAL;
            }
            return Danger.SAFE;
        }

        if (isZulrah(regionId) && client.getVarbitValue(VarbitID.ZULRAH_REVIVE) == 0 && client.getVarbitValue(VarbitID.WESTERN_DIARY_ELITE_COMPLETE) > 0) {
            // Western Provinces Elite diary completion allows 1 free daily resurrection: https://github.com/pajlads/DinkPlugin/issues/548
            return exceptions.contains(ExceptionalDeath.DIARY_RESURRECTION) ? Danger.EXCEPTIONAL : Danger.SAFE;
        }

        if (isBarbarianAssault(regionId) || isNightmareZone(regionId)  || isMageTrainingArena(regionId)
                || isPestControl(client) || isGalvekRematch(client, regionId)) {
            // All PvM activities are dangerous for Hardcore group iron players
            return Utils.getAccountType(client) == AccountType.HARDCORE_GROUP_IRONMAN ? Danger.DANGEROUS : Danger.SAFE;
        }

        if (isCastleWars(regionId) || isClanWars(regionId) || isSoulWars(regionId) || isPlayerOwnedHouse(regionId)
                || isLastManStanding(client) || isTzHaarFightPit(regionId)) {
            return Danger.SAFE;
        }

        return Danger.DANGEROUS;
    }

    private Danger checkException(boolean dangerous, Set<ExceptionalDeath> exceptions, ExceptionalDeath exception) {
        if (dangerous) return Danger.DANGEROUS;
        if (exceptions.contains(exception)) return Danger.EXCEPTIONAL;
        return Danger.SAFE;
    }

}

package haexporterplugin;

import com.google.gson.Gson;
import haexporterplugin.data.HAConnection;
import haexporterplugin.utils.ConfigUtils;
import haexporterplugin.utils.HomeAssistUtils;
import net.runelite.client.ui.FontManager;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import javax.swing.AbstractButton;
import javax.swing.JLabel;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class HAExporterPanelTest
{
	private static final String[] FONT_FILES = {"runescape.ttf", "runescape_small.ttf", "runescape_bold.ttf"};

	private final HAExporterPanel panel = new HAExporterPanel();
	private final List<HAConnection> connections = new ArrayList<>();

	@Before
	public void setUp()
	{
		// Every global toggle on, so only the per-connection toggles decide the status line
		panel.config = TestUtils.configWithEverythingOn();
		panel.homeAssistUtils = mock(HomeAssistUtils.class);
		panel.configUtils = mock(ConfigUtils.class);
		panel.gson = new Gson();

		when(panel.configUtils.getStoredConnections()).thenReturn(connections);
	}

	@After
	public void tearDown()
	{
		panel.onDeactivate();
	}

	// The side panel is drawn in RuneLite's RuneScape font. macOS has no fallback font for it,
	// so any character the font lacks shows up there as a "missing glyph" box.
	@Test
	public void testHomeAndSettingsViewsOnlyUseCharactersInTheRuneScapeFont() throws Exception
	{
		addOneConnectionOfEachKind();
		panel.initialize();

		assertFalse(textsIn(panel).isEmpty());
		assertAllDisplayable(textsIn(panel));

		// The disabled connection's settings also show why it was disabled
		settingsButtons().get(3).doClick();

		assertTrue(textsIn(panel).contains("Connection Settings"));
		assertTrue(textsIn(panel).contains("https://disabled.example"));
		assertAllDisplayable(textsIn(panel));
	}

	@Test
	public void testStatusLinesAndSettingsButtonsShowAnIcon()
	{
		addOneConnectionOfEachKind();
		panel.initialize();

		assertNotNull(labelContaining("All enabled").getIcon());
		assertNotNull(labelContaining("Disabled: Inv, Loot").getIcon());
		assertNotNull(labelContaining("Paused").getIcon());
		assertNotNull(labelContaining("Unauthorized").getIcon());
		assertEquals(4, settingsButtons().size());
		assertNotNull(settingsButtons().get(0).getIcon());
	}

	// A disabled connection sends nothing, so its per-toggle status would only contradict the warning
	@Test
	public void testDisabledConnectionHidesToggleStatus()
	{
		HAConnection disabled = disabledConnection();
		HAConnection disabledWithTogglesOff = connectionWithTogglesOff();
		disabledWithTogglesOff.setEnabled(false);
		connections.add(disabled);
		connections.add(disabledWithTogglesOff);

		panel.initialize();

		assertNotNull(labelContaining("Unauthorized"));
		assertNull(findLabel("All enabled"));
		assertNull(findLabel("Disabled:"));
	}

	private void addOneConnectionOfEachKind()
	{
		connections.add(healthyConnection());
		connections.add(pausedConnection());
		connections.add(connectionWithTogglesOff());
		connections.add(disabledConnection());
	}

	private static HAConnection healthyConnection()
	{
		HAConnection connection = new HAConnection("https://ha.example", "token-healthy");
		connection.setFriendlyName("Main HA");
		return connection;
	}

	private HAConnection pausedConnection()
	{
		HAConnection connection = new HAConnection("https://paused.example", "token-paused");
		when(panel.homeAssistUtils.getPausedUntil(connection)).thenReturn(System.currentTimeMillis() + 90_000L);
		when(panel.homeAssistUtils.getQueuedCount(connection)).thenReturn(2);
		return connection;
	}

	private static HAConnection connectionWithTogglesOff()
	{
		HAConnection connection = new HAConnection("https://partial.example", "token-partial");
		connection.setIncludeInventory(false);
		connection.setIncludeLootEvents(false);
		return connection;
	}

	private static HAConnection disabledConnection()
	{
		HAConnection connection = new HAConnection("https://disabled.example", "token-disabled");
		connection.setEnabled(false);
		connection.setDisabledReason("Unauthorized (401)");
		return connection;
	}

	private List<AbstractButton> settingsButtons()
	{
		return componentsIn(panel).stream()
			.filter(component -> component instanceof AbstractButton && "Settings".equals(((AbstractButton) component).getToolTipText()))
			.map(component -> (AbstractButton) component)
			.collect(Collectors.toList());
	}

	private JLabel labelContaining(String fragment)
	{
		JLabel label = findLabel(fragment);
		assertNotNull("No label containing \"" + fragment + "\" in " + textsIn(panel), label);
		return label;
	}

	// The first visible label whose text contains the fragment, or null
	private JLabel findLabel(String fragment)
	{
		return componentsIn(panel).stream()
			.filter(component -> component instanceof JLabel && component.isVisible())
			.map(component -> (JLabel) component)
			.filter(label -> label.getText() != null && label.getText().contains(fragment))
			.findFirst()
			.orElse(null);
	}

	private static void assertAllDisplayable(List<String> texts) throws Exception
	{
		for (String fontFile : FONT_FILES)
		{
			// Loaded straight from the file: FontManager's own fonts gain a system fallback on
			// Windows and Linux, which would hide the missing glyphs this is looking for
			Font font;
			try (InputStream in = FontManager.class.getResourceAsStream(fontFile))
			{
				font = Font.createFont(Font.TRUETYPE_FONT, in);
			}

			for (String text : texts)
			{
				int index = font.canDisplayUpTo(text);
				if (index != -1)
				{
					fail(String.format("U+%04X in \"%s\" is not in %s", (int) text.charAt(index), text, fontFile));
				}
			}
		}
	}

	private static List<String> textsIn(Container root)
	{
		List<String> texts = new ArrayList<>();
		for (Component component : componentsIn(root))
		{
			String text = null;
			if (component instanceof JLabel)
			{
				text = ((JLabel) component).getText();
			}
			else if (component instanceof AbstractButton)
			{
				text = ((AbstractButton) component).getText();
			}

			if (text != null && !text.isEmpty())
			{
				texts.add(text);
			}
		}
		return texts;
	}

	private static List<Component> componentsIn(Container root)
	{
		List<Component> components = new ArrayList<>();
		for (Component child : root.getComponents())
		{
			components.add(child);
			if (child instanceof Container)
			{
				components.addAll(componentsIn((Container) child));
			}
		}
		return components;
	}
}

