		when(config.sendRate()).thenReturn(100);
		// Level-up filter defaults: send every level
		when(config.levelMinValue()).thenReturn(1);
		when(config.levelInterval()).thenReturn(1);
		when(config.levelIncludeVirtual()).thenReturn(true);
		when(config.levelIncludeCombat()).thenReturn(true);
		// TickUtils counts ticks since the last send, which is usually well past the init delay
		when(tickUtils.getTickCount()).thenReturn(60);

		Injector injector = TestUtils.injector(Map.of(Client.class, client, HAExporterConfig.class, config, TickUtils.class, tickUtils));
		messageBuilder = injector.getInstance(MessageBuilder.class);
		levelNotifier = injector.getInstance(LevelNotifier.class);
	}

	@Test
	public void testNoLevelUpAfterLoggingIntoAnotherAccount()
	{
		tick(5);

		levelNotifier.onGameStateChanged(gameState(GameState.LOGIN_SCREEN));
		setAllLevels(70);
		tick(5);

		assertNoLevelUp();
	}

	@Test
	public void testBaselineWaitsForTheNewWorldToLoad()
	{
		tick(5);

		hop();
		levelNotifier.onTick(); // first tick after the hop: the old character's stats can still be reported
		setAllLevels(99); // e.g. a Leagues character
		tick(5);

		assertNoLevelUp();
	}

	@Test
	public void testRealLevelUpAfterHopIsStillReported()
	{
		tick(5);
		hop();
		tick(5);

		levels.put(Skill.ATTACK, 51);
		levelNotifier.onTick();

		verify(tickUtils).sendNow();
		assertEquals(1, messageBuilder.getRoot().getEvents().size());
	}

	@Test
	public void testIntervalFiltersEventsButStatsStillUpdate()
	{
		when(config.levelInterval()).thenReturn(5);
		tick(5);

		levels.put(Skill.MINING, 51);
		levelNotifier.onTick();
		assertNoLevelUp();
		assertEquals(Integer.valueOf(51), messageBuilder.getPlayer().getStats().getSkills().get("Mining").getLevel());

		levels.put(Skill.MINING, 55);
		levelNotifier.onTick();
		assertEquals(1, messageBuilder.getRoot().getEvents().size());
	}

	@Test
	public void testCombatLevelCanBeTurnedOff()
	{
		when(config.levelIncludeCombat()).thenReturn(false);
		tick(5);

		// Raising the combat skills raises the combat level too
		for (Skill skill : new Skill[]{Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS, Skill.PRAYER})
		{
			levels.put(skill, 60);
		}
		levelNotifier.onTick();

		Map<?, ?> event = (Map<?, ?>) messageBuilder.getRoot().getEvents().get(0);
		String json = new Gson().toJson(event.get("data"));
		assertTrue(json.contains("Attack"));
		assertFalse(json.contains("Combat"));
	}

	@Test
	public void testShouldSend()
	{
		// The defaults send every level, virtual levels and the combat level included
		assertTrue(LevelNotifier.shouldSend("Attack", 2, 1, 1, true, true));
		assertTrue(LevelNotifier.shouldSend("Attack", 105, 1, 1, true, true));
		assertTrue(LevelNotifier.shouldSend("Combat", 50, 1, 1, true, true));
		// Minimum level
		assertFalse(LevelNotifier.shouldSend("Attack", 69, 70, 1, true, true));
		assertTrue(LevelNotifier.shouldSend("Attack", 70, 70, 1, true, true));
		// 99 is sent whatever the interval
		assertTrue(LevelNotifier.shouldSend("Mining", 99, 1, 10, true, true));
		// Without virtual levels; the combat level is never virtual
		assertFalse(LevelNotifier.shouldSend("Mining", 100, 1, 1, false, true));
		assertTrue(LevelNotifier.shouldSend("Mining", 99, 1, 1, false, true));
		assertTrue(LevelNotifier.shouldSend("Combat", 100, 1, 1, false, true));
	}

	private void hop()
	{
		levelNotifier.onGameStateChanged(gameState(GameState.HOPPING));
	}

	private void tick(int count)
	{
		for (int i = 0; i < count; i++)
		{
			levelNotifier.onTick();
		}
	}

	private void setAllLevels(int level)
	{
		for (Skill skill : Skill.values())
		{
			levels.put(skill, level);
		}
	}

	private void assertNoLevelUp()
	{
		verify(tickUtils, never()).sendNow();
		assertTrue(messageBuilder.getRoot().getEvents().isEmpty());
	}

	private static GameStateChanged gameState(GameState state)
	{
		GameStateChanged event = new GameStateChanged();
		event.setGameState(state);
		return event;
	}
}

package haexporterplugin.notifiers;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.inject.Injector;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.TestUtils;
import haexporterplugin.utils.MessageBuilder;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

import java.util.Map;
import java.util.Set;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class LocationNotifierTest
{
	private final Gson gson = new Gson();
	private final HAExporterConfig config = mock(HAExporterConfig.class);
	private MessageBuilder messageBuilder;
	private LocationNotifier locationNotifier;

	@Before
	public void setUp()
	{
		when(config.includeLocation()).thenReturn(true);

		Injector injector = TestUtils.injector(Map.of(HAExporterConfig.class, config));
		messageBuilder = injector.getInstance(MessageBuilder.class);
		locationNotifier = injector.getInstance(LocationNotifier.class);
	}

	/* ============================
	   TRAIL
	   ============================ */

	@Test
	public void testFirstLocationStartsTheTrail()
	{
		long before = System.currentTimeMillis();
		walkTo(3222, 3218, 0);
		long after = System.currentTimeMillis();

		JsonArray trail = trail();
		assertEquals(1, trail.size());
		JsonObject point = trail.get(0).getAsJsonObject();
		assertEquals(3222, point.get("x").getAsInt());
		assertEquals(3218, point.get("y").getAsInt());
		assertEquals(0, point.get("plane").getAsInt());
		assertFalse(point.get("isOnBoat").getAsBoolean());
		long timestamp = point.get("timestamp").getAsLong();
		assertTrue(timestamp >= before && timestamp <= after);
		// A point holds only position and time
		assertEquals(Set.of("x", "y", "plane", "isOnBoat", "timestamp"), point.keySet());
	}

	@Test
	public void testLocationStillHoldsTheLatestTile()
	{
		walkTo(3222, 3218, 0);
		walkTo(3223, 3219, 0);

		JsonObject location = player().getAsJsonObject("location");
		assertEquals(3223, location.get("x").getAsInt());
		assertEquals(3219, location.get("y").getAsInt());
	}

	@Test
	public void testStandingStillAddsNoPoints()
	{
		walkTo(3222, 3218, 0);
		walkTo(3222, 3218, 0);
		walkTo(3222, 3218, 0);

		assertEquals(1, trail().size());
	}

	@Test
	public void testPlaneChangeIsRecorded()
	{
		walkTo(3205, 3209, 0);
		walkTo(3205, 3209, 1);

		JsonArray trail = trail();
		assertEquals(2, trail.size());
		assertPoint(trail, 1, 3205, 3209, 1);
	}

	@Test
	public void testBoatStateChangeIsRecorded()
	{
		walkTo(3050, 3193, 0);
		locationNotifier.recordLocation(new WorldPoint(3050, 3193, 0), true);

		JsonArray trail = trail();
		assertEquals(2, trail.size());
		assertTrue(trail.get(1).getAsJsonObject().get("isOnBoat").getAsBoolean());
	}

	@Test
	public void testTrailKeepsOnlyTheNewestPoints()
	{
		int max = MessageBuilder.MAX_LOCATION_TRAIL_POINTS;
		for (int i = 0; i <= max; i++)
		{
			walkTo(3000 + i, 3218, 0);
		}

		JsonArray trail = trail();
		assertEquals(max, trail.size());
		assertPoint(trail, 0, 3001, 3218, 0);
		assertPoint(trail, max - 1, 3000 + max, 3218, 0);
	}

	@Test
	public void testSameTileIsRecordedAgainAfterReset()
	{
		// After logging back in on the same tile, the trail still starts with that tile
		walkTo(3222, 3218, 0);
		locationNotifier.reset();
		walkTo(3222, 3218, 0);

		assertEquals(2, trail().size());
	}

	/* ============================
	   SHARE LOCATION SWITCH
	   ============================ */

	@Test
	public void testNothingRecordedWhileLocationSharingIsOff()
	{
		when(config.includeLocation()).thenReturn(false);

		walkTo(3164, 3487, 0);
		walkTo(3165, 3487, 0);

		assertEquals(0, trail().size());
	}

	@Test
	public void testCurrentTileIsRecordedWhenLocationSharingIsTurnedOn()
	{
		when(config.includeLocation()).thenReturn(false);
		walkTo(3164, 3487, 0);

		when(config.includeLocation()).thenReturn(true);
		walkTo(3164, 3487, 0);

		JsonArray trail = trail();
		assertEquals(1, trail.size());
		assertPoint(trail, 0, 3164, 3487, 0);
	}

	/* ============================
	   HELPERS
	   ============================ */

	private void walkTo(int x, int y, int plane)
	{
		locationNotifier.recordLocation(new WorldPoint(x, y, plane), false);
	}

	private JsonObject player()
	{
		return gson.fromJson(messageBuilder.build(), JsonObject.class).getAsJsonObject("player");
	}

	private JsonArray trail()
	{
		return player().getAsJsonArray("locationTrail");
	}

	private static void assertPoint(JsonArray trail, int index, int x, int y, int plane)
	{
		JsonObject point = trail.get(index).getAsJsonObject();
		assertEquals(x, point.get("x").getAsInt());
		assertEquals(y, point.get("y").getAsInt());
		assertEquals(plane, point.get("plane").getAsInt());
	}
}

package haexporterplugin.notifiers;

import com.google.inject.Injector;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.TestUtils;
import haexporterplugin.utils.MessageBuilder;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Player;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Before;
import org.junit.Test;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

public class LootNotifierTest
{
	private static final int COIN_POUCH_ID = 1;
	private static final int ARROW_ID = 2;
	private static final int BOLT_ID = 3;

	private final Client client = mock(Client.class);
	private final HAExporterConfig config = mock(HAExporterConfig.class);
	private MessageBuilder messageBuilder;
	private LootNotifier lootNotifier;

	@Before
	public void setUp()
	{
		when(config.minLootValue()).thenReturn(25_000);
		when(config.lootItemAllowlist()).thenReturn("");
		when(config.lootItemDenylist()).thenReturn("");
		when(config.lootSourceDenylist()).thenReturn("");
		when(config.lootIncludePlayer()).thenReturn(true);
		when(config.lootIncludePickpocket()).thenReturn(true);
		when(config.lootIncludePkChest()).thenReturn(true);

		ItemComposition pouch = item(COIN_POUCH_ID, "Coin pouch");
		ItemComposition arrow = item(ARROW_ID, "Dragon arrow");
		ItemComposition bolt = item(BOLT_ID, "Dragon bolts");
		ItemManager itemManager = mock(ItemManager.class);
		when(itemManager.getItemComposition(anyInt())).thenAnswer(inv ->
		{
			int id = inv.getArgument(0);
			return id == COIN_POUCH_ID ? pouch : id == ARROW_ID ? arrow : bolt;
		});
		when(itemManager.getItemPrice(COIN_POUCH_ID)).thenReturn(50_000L);
		when(itemManager.getItemPrice(ARROW_ID)).thenReturn(15_000L);
		when(itemManager.getItemPrice(BOLT_ID)).thenReturn(15_000L);

		Injector injector = TestUtils.injector(Map.of(Client.class, client, ItemManager.class, itemManager, HAExporterConfig.class, config));
		messageBuilder = injector.getInstance(MessageBuilder.class);
		lootNotifier = injector.getInstance(LootNotifier.class);
		lootNotifier.init();
	}

	@Test
	public void testPickpocketLootIsSentUntilTurnedOff()
	{
		pickpocket();
		assertEquals(List.of("loot"), eventTypes());

		when(config.lootIncludePickpocket()).thenReturn(false);
		pickpocket();
		assertEquals(List.of("loot"), eventTypes());
	}

	@Test
	public void testPkChestUsesTotalValueUntilTurnedOff()
	{
		pkChest();
		assertEquals(List.of("pkLoot"), eventTypes());

		when(config.lootIncludePkChest()).thenReturn(false);
		pkChest();
		assertEquals(List.of("pkLoot"), eventTypes());
	}

	@Test
	public void testPkLootCanBeTurnedOff()
	{
		when(config.lootIncludePlayer()).thenReturn(false);
		Player victim = mock(Player.class);
		when(victim.getName()).thenReturn("Victim");

		lootNotifier.onPlayerLootReceived(new PlayerLootReceived(victim, List.of(new ItemStack(COIN_POUCH_ID, 1))));

		assertTrue(eventTypes().isEmpty());
		// Returns before the safe-area check even looks at the player
		verify(client, never()).getLocalPlayer();
	}

	private void pickpocket()
	{
		lootNotifier.onLootReceived(new LootReceived("Master Farmer", -1, LootRecordType.PICKPOCKET,
				List.of(new ItemStack(COIN_POUCH_ID, 1)), 1, null));
	}

	// Two items each below the 25k minimum, together above it
	private void pkChest()
	{
		lootNotifier.onLootReceived(new LootReceived("Loot Chest", -1, LootRecordType.EVENT,
				List.of(new ItemStack(ARROW_ID, 1), new ItemStack(BOLT_ID, 1)), 1, null));
	}

	private List<Object> eventTypes()
	{
		return messageBuilder.getRoot().getEvents().stream()
				.map(event -> ((Map<?, ?>) event).get("type"))
				.collect(Collectors.toList());
	}

	private static ItemComposition item(int id, String name)
	{
		ItemComposition composition = mock(ItemComposition.class);
		when(composition.getId()).thenReturn(id);
		when(composition.getName()).thenReturn(name);
		return composition;
	}
}

package haexporterplugin.notifiers;

import com.google.inject.Injector;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.TestUtils;
import haexporterplugin.enums.CombatTaskTier;
import haexporterplugin.enums.DiaryTier;
import haexporterplugin.utils.MessageBuilder;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import org.junit.Before;
import org.junit.Test;

import java.util.Map;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TaskTierNotifierTest
{
	private static final String HARD_DIARY = "Well done! You have completed a hard task in the Varrock area. Your Achievement Diary has been updated.";
	private static final String ELITE_DIARY = "Well done! You have completed an elite task in the Varrock area. Your Achievement Diary has been updated.";
	private static final String MEDIUM_TASK = "Congratulations, you've completed a medium combat task: Hitting Them Where It Hurts.";
	private static final String MASTER_TASK = "Congratulations, you've completed a master combat task: Perfect Zulrah.";

	private final HAExporterConfig config = mock(HAExporterConfig.class);
	private MessageBuilder messageBuilder;
	private AchievementDiaryNotifier diaryNotifier;
	private CombatTaskNotifier combatTaskNotifier;

	@Before
	public void setUp()
	{
		when(config.diaryMinTier()).thenReturn(DiaryTier.EASY);
		when(config.combatTaskMinTier()).thenReturn(CombatTaskTier.EASY);

		Injector injector = TestUtils.injector(Map.of(HAExporterConfig.class, config));
		messageBuilder = injector.getInstance(MessageBuilder.class);
		diaryNotifier = injector.getInstance(AchievementDiaryNotifier.class);
		combatTaskNotifier = injector.getInstance(CombatTaskNotifier.class);
	}

	@Test
	public void testDiaryMinimumTierSkipsEasierTasks()
	{
		diaryNotifier.onChatMessage(chat(HARD_DIARY));
		assertEquals(1, eventCount());

		when(config.diaryMinTier()).thenReturn(DiaryTier.ELITE);
		diaryNotifier.onChatMessage(chat(HARD_DIARY));
		assertEquals(1, eventCount());

		diaryNotifier.onChatMessage(chat(ELITE_DIARY));
		assertEquals(2, eventCount());
	}

	@Test
	public void testCombatTaskMinimumTierSkipsEasierTasks()
	{
		combatTaskNotifier.onChatMessage(chat(MEDIUM_TASK));
		assertEquals(1, eventCount());

		when(config.combatTaskMinTier()).thenReturn(CombatTaskTier.HARD);
		combatTaskNotifier.onChatMessage(chat(MEDIUM_TASK));
		assertEquals(1, eventCount());

		combatTaskNotifier.onChatMessage(chat(MASTER_TASK));
		assertEquals(2, eventCount());
	}

	private int eventCount()
	{
		return messageBuilder.getRoot().getEvents().size();
	}

	private static ChatMessage chat(String message)
	{
		ChatMessage event = new ChatMessage();
		event.setType(ChatMessageType.GAMEMESSAGE);
		event.setMessage(message);
		return event;
	}
}

package haexporterplugin.utils;

import haexporterplugin.utils.ConnectionBackoff.Outcome;
import org.junit.Test;

import java.time.Instant;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.*;

public class ConnectionBackoffTest
{
	private static final String KEY = "http://ha.local:8123\ntoken";
	private static final long SECOND = 1000L;
	private static final long MINUTE = 60 * SECOND;

	private long now = 1_700_000_000_000L;
	private final ConnectionBackoff backoff = new ConnectionBackoff(() -> now);

	@Test
	public void testFirstFailureIsReportedOnce()
	{
		assertTrue(backoff.recordFailure(KEY));

		now += 30 * SECOND;
		assertFalse(backoff.recordFailure(KEY));

		backoff.recordSuccess(KEY);
		assertTrue(backoff.recordFailure(KEY));
	}

	@Test
	public void testFailureWhilePausedDoesNotEscalate()
	{
		backoff.recordFailure(KEY);
		long pausedUntil = backoff.getPausedUntil(KEY);

		now += 10 * SECOND;
		assertFalse(backoff.recordFailure(KEY));
		assertEquals(pausedUntil, backoff.getPausedUntil(KEY));

		now = pausedUntil;
		backoff.recordFailure(KEY);
		assertEquals(now + 60 * SECOND, backoff.getPausedUntil(KEY));
	}

	@Test
	public void testSuccessResetsBackoff()
	{
		backoff.recordFailure(KEY);
		now += 30 * SECOND;
		backoff.recordFailure(KEY);
		assertTrue(backoff.isPaused(KEY));

		backoff.recordSuccess(KEY);
		assertFalse(backoff.isPaused(KEY));
		assertEquals(0, backoff.getPausedUntil(KEY));

		backoff.recordFailure(KEY);
		assertEquals(now + 30 * SECOND, backoff.getPausedUntil(KEY));
	}

	@Test
	public void testRetryAfterPausesUntilGivenTimeAndExpires()
	{
		long until = now + 45 * SECOND;
		assertTrue(backoff.recordRetryAfter(KEY, until));
		assertTrue(backoff.isPaused(KEY));
		assertEquals(until, backoff.getPausedUntil(KEY));

		now = until - 1;
		assertTrue(backoff.isPaused(KEY));

		now = until;
		assertFalse(backoff.isPaused(KEY));
		assertEquals(0, backoff.getPausedUntil(KEY));
	}

	@Test
	public void testRetryAfterDoesNotAdvanceExponentialBackoff()
	{
		backoff.recordRetryAfter(KEY, now + 5 * MINUTE);
		now += 5 * MINUTE;

		backoff.recordFailure(KEY);
		assertEquals(now + 30 * SECOND, backoff.getPausedUntil(KEY));
	}

	@Test
	public void testRetryAfterIsKeptWithinBounds()
	{
		backoff.recordRetryAfter(KEY, now + 60 * MINUTE);
		assertEquals(now + 10 * MINUTE, backoff.getPausedUntil(KEY));

		backoff.clear(KEY);
		backoff.recordRetryAfter(KEY, now - MINUTE);
		assertEquals(now + SECOND, backoff.getPausedUntil(KEY));
	}

	@Test
	public void testParseRetryAfter()
	{
		assertEquals(Long.valueOf(now + 120 * SECOND), ConnectionBackoff.parseRetryAfter("120", now));
		assertEquals(Long.valueOf(now + 5 * SECOND), ConnectionBackoff.parseRetryAfter(" 5 ", now));
		assertEquals(Long.valueOf(now), ConnectionBackoff.parseRetryAfter("0", now));
		assertEquals(Long.valueOf(Instant.parse("2015-10-21T07:28:00Z").toEpochMilli()),
			ConnectionBackoff.parseRetryAfter("Wed, 21 Oct 2015 07:28:00 GMT", now));

		for (String invalid : new String[]{null, "", "   ", "soon", "-5", "1.5", "99999999999999999999", "2015-10-21T07:28:00Z"})
		{
			assertNull(invalid, ConnectionBackoff.parseRetryAfter(invalid, now));
		}
	}

	@Test
	public void testQueueDropsOldestBeyondLimit()
	{
		for (int i = 1; i <= ConnectionBackoff.MAX_QUEUED_PAYLOADS + 1; i++)
		{
			backoff.enqueue(KEY, "payload-" + i);
		}

		assertEquals(ConnectionBackoff.MAX_QUEUED_PAYLOADS, backoff.getQueuedCount(KEY));
		assertEquals("payload-2", backoff.beginDrain(KEY));
	}

	@Test
	public void testQueueDropsEntriesOlderThanTenMinutes()
	{
		backoff.enqueue(KEY, "old");
		now += 5 * MINUTE;
		backoff.enqueue(KEY, "new");

		now += 5 * MINUTE;
		assertEquals(2, backoff.getQueuedCount(KEY));

		now += 1;
		assertEquals(1, backoff.getQueuedCount(KEY));
		assertEquals("new", backoff.beginDrain(KEY));
	}

	@Test
	public void testNewestQueuedPayloadCanBeReplacedByAMergedOne()
	{
		backoff.enqueue(KEY, "a");
		backoff.enqueue(KEY, "b");

		String candidate = backoff.getMergeCandidate(KEY);
		assertEquals("b", candidate);
		assertTrue(backoff.replaceNewest(KEY, candidate, "b+c"));

		assertEquals(2, backoff.getQueuedCount(KEY));
		assertEquals("a", backoff.beginDrain(KEY));
		backoff.completeDrain(KEY, true);
		assertEquals("b+c", backoff.beginDrain(KEY));
	}

	@Test
	public void testPayloadBeingResentIsNoMergeCandidate()
	{
		backoff.enqueue(KEY, "a");
		assertEquals("a", backoff.beginDrain(KEY));

		assertNull(backoff.getMergeCandidate(KEY));
	}

	@Test
	public void testReplaceFailsWhenTheCandidateStartedBeingResent()
	{
		backoff.enqueue(KEY, "a");
		String candidate = backoff.getMergeCandidate(KEY);
		assertEquals("a", backoff.beginDrain(KEY));

		assertFalse(backoff.replaceNewest(KEY, candidate, "a+b"));

		backoff.completeDrain(KEY, true);
		assertEquals(0, backoff.getQueuedCount(KEY));
	}

	@Test
	public void testReplaceFailsWhenAnotherPayloadWasQueuedMeanwhile()
	{
		backoff.enqueue(KEY, "a");
		String candidate = backoff.getMergeCandidate(KEY);
		backoff.enqueue(KEY, "b");

		assertFalse(backoff.replaceNewest(KEY, candidate, "a+c"));

		assertEquals(2, backoff.getQueuedCount(KEY));
		assertEquals("a", backoff.beginDrain(KEY));
	}

	@Test
	public void testPayloadIsOnlyAMergeCandidateForAMinute()
	{
		backoff.enqueue(KEY, "a");

		now += MINUTE - 1;
		assertEquals("a", backoff.getMergeCandidate(KEY));

		now += 1;
		assertNull(backoff.getMergeCandidate(KEY));
	}

	@Test
	public void testMergedPayloadKeepsItsQueueTime()
	{
		backoff.enqueue(KEY, "a");
		now += 30 * SECOND;
		assertTrue(backoff.replaceNewest(KEY, backoff.getMergeCandidate(KEY), "a+b"));

		now += 9 * MINUTE + 30 * SECOND;
		assertEquals(1, backoff.getQueuedCount(KEY));

		now += 1;
		assertEquals(0, backoff.getQueuedCount(KEY));
	}

	@Test
	public void testBeginDrainReturnsNullWhilePaused()
	{
		backoff.enqueue(KEY, "a");
		backoff.recordFailure(KEY);

		assertNull(backoff.beginDrain(KEY));

		now = backoff.getPausedUntil(KEY);
		assertEquals("a", backoff.beginDrain(KEY));
	}

	@Test
	public void testBeginDrainReturnsNullWhileInFlight()
	{
		backoff.enqueue(KEY, "a");
		backoff.enqueue(KEY, "b");

		assertEquals("a", backoff.beginDrain(KEY));
		assertNull(backoff.beginDrain(KEY));

		backoff.completeDrain(KEY, true);
		assertEquals("b", backoff.beginDrain(KEY));
	}

	@Test
	public void testDeliveredDrainDoesNotRemoveNewerEntryWhenHeadWasPushedOut()
	{
		backoff.enqueue(KEY, "payload-0");
		assertEquals("payload-0", backoff.beginDrain(KEY));

		for (int i = 1; i <= ConnectionBackoff.MAX_QUEUED_PAYLOADS; i++)
		{
			backoff.enqueue(KEY, "payload-" + i);
		}
		backoff.completeDrain(KEY, true);

		assertEquals(ConnectionBackoff.MAX_QUEUED_PAYLOADS, backoff.getQueuedCount(KEY));
		assertEquals("payload-1", backoff.beginDrain(KEY));
	}

	@Test
	public void testClearResetsEverything()
	{
		backoff.enqueue(KEY, "a");
		backoff.recordFailure(KEY);

		backoff.clear(KEY);

		assertFalse(backoff.isPaused(KEY));
		assertEquals(0, backoff.getQueuedCount(KEY));
		assertNull(backoff.beginDrain(KEY));

		backoff.recordFailure(KEY);
		assertEquals(now + 30 * SECOND, backoff.getPausedUntil(KEY));
	}

	@Test
	public void testClearAllResetsEveryConnection()
	{
		String other = "http://other.local:8123\ntoken";
		backoff.enqueue(KEY, "a");
		backoff.recordFailure(KEY);
		backoff.enqueue(other, "b");
		backoff.recordFailure(other);

		backoff.clearAll();

		for (String key : new String[]{KEY, other})
		{
			assertFalse(backoff.isPaused(key));
			assertEquals(0, backoff.getQueuedCount(key));
			assertNull(backoff.beginDrain(key));
		}
	}

	@Test
	public void testConnectionsAreIndependent()
	{
		String other = "http://other.local:8123\ntoken";
		backoff.recordFailure(KEY);
		backoff.enqueue(KEY, "a");

		assertFalse(backoff.isPaused(other));
		assertEquals(0, backoff.getQueuedCount(other));
	}

	@Test
	public void testClassify()
	{
		Map<Outcome, List<Integer>> codes = Map.of(
			Outcome.SUCCESS, List.of(200, 204),
			Outcome.UNAUTHORIZED, List.of(401),
			Outcome.GONE, List.of(410),
			Outcome.RETRY_AFTER, List.of(429, 503),
			// A 404 says the endpoint isn't there (yet), not that it refused the payload: Home Assistant answers it
			// until the integration has registered its endpoints
			Outcome.BACKOFF, List.of(404, 500, 502, 504),
			Outcome.REJECTED, List.of(302, 400, 403, 405, 413, 422));
		codes.forEach((outcome, list) -> list.forEach(code -> assertEquals("HTTP " + code, outcome, ConnectionBackoff.classify(code))));
	}
}

package haexporterplugin.utils;

import com.google.common.util.concurrent.Uninterruptibles;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import haexporterplugin.TestUtils;
import okhttp3.OkHttpClient;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import static org.junit.Assert.*;

public class HomeAssistUtilsDeliveryTest extends HomeAssistUtilsTestBase
{
	private static final long TICK = 600L;
	private static final String LEVEL_UP = "{\"type\":\"levelUp\",\"data\":[{\"skill\":\"Attack\",\"level\":99}],\"eventId\":\"e\",\"timestamp\":1}";

	/* ============================
	   CALLING THREAD
	   ============================ */

	// sendMessage runs on the game thread, which must never wait for an endpoint
	@Test(timeout = 10_000)
	public void testSendMessageDoesNotWaitForTheEndpoint() throws Exception
	{
		CountDownLatch requestStarted = new CountDownLatch(1);
		CountDownLatch answer = new CountDownLatch(1);
		OkHttpClient unansweredClient = new OkHttpClient.Builder()
			.addInterceptor(chain ->
			{
				requestStarted.countDown();
				Uninterruptibles.awaitUninterruptibly(answer);
				return response(chain.request(), 200, "{}");
			})
			.build();
		TestUtils.setField(homeAssistUtils, "okHttpClient", unansweredClient);

		try
		{
			homeAssistUtils.sendMessage(snapshot(T0, T0 - TICK));
			assertTrue(requestStarted.await(5, TimeUnit.SECONDS));

			// The first request is still unanswered
			homeAssistUtils.sendMessage(snapshot(T0 + 10 * SECOND, T0 + 9 * SECOND));
		}
		finally
		{
			answer.countDown();
			unansweredClient.dispatcher().executorService().shutdown();
		}
	}

	/* ============================
	   LOCATION TRAIL
	   ============================ */

	@Test
	public void testSnapshotWithTrailLinesUpBehindPayloadsStillWaiting()
	{
		responseCode = 500;
		homeAssistUtils.sendMessage(payload(T0, LEVEL_UP, T0 - TICK));

		// The pause is over, but the queued payload has not been resent yet
		responseCode = 200;
		now = homeAssistUtils.getPausedUntil(connection);
		homeAssistUtils.sendMessage(snapshot(T0 + 30 * SECOND, T0 + 29 * SECOND));

		assertEquals(3, sentBodies.size());
		assertEquals(List.of(T0 - TICK), trailTimestamps(sentBodies.get(1)));
		assertEquals(List.of(T0 + 29 * SECOND), trailTimestamps(sentBodies.get(2)));
	}

	@Test
	public void testSnapshotWithoutTrailOrEventsIsNotRetried()
	{
		responseCode = 500;
		homeAssistUtils.sendMessage(snapshot(T0));
		homeAssistUtils.sendMessage(snapshot(T0 + 10 * SECOND));
		assertEquals(0, homeAssistUtils.getQueuedCount(connection));

		responseCode = 200;
		endPause();

		assertEquals(1, sentBodies.size());
	}

	@Test
	public void testTrailIsNotKeptForConnectionThatDoesNotReceiveLocation()
	{
		connection.setIncludeLocation(false);

		responseCode = 500;
		homeAssistUtils.sendMessage(snapshot(T0, T0 - TICK));
		homeAssistUtils.sendMessage(snapshot(T0 + 10 * SECOND, T0 + 9 * SECOND));

		assertEquals(0, homeAssistUtils.getQueuedCount(connection));
	}

	/* ============================
	   COMBINING QUEUED SNAPSHOTS
	   ============================ */

	@Test
	public void testTrailSnapshotsQueuedCloseTogetherAreCombined()
	{
		responseCode = 500;
		homeAssistUtils.sendMessage(snapshot(T0, T0 - TICK));
		now += 10 * SECOND;
		homeAssistUtils.sendMessage(snapshot(T0 + 10 * SECOND, T0 + 9 * SECOND));
		assertEquals(1, homeAssistUtils.getQueuedCount(connection));

		responseCode = 200;
		endPause();

		assertEquals(2, sentBodies.size());
		assertEquals(List.of(T0 - TICK, T0 + 9 * SECOND), trailTimestamps(sentBodies.get(1)));
		assertEquals(T0 + 10 * SECOND, timestamp(sentBodies.get(1)));
	}

	@Test
	public void testTrailSnapshotIsNotCombinedWithPayloadWithEvents()
	{
		responseCode = 500;
		homeAssistUtils.sendMessage(payload(T0, LEVEL_UP, T0 - TICK));
		homeAssistUtils.sendMessage(snapshot(T0 + 10 * SECOND, T0 + 9 * SECOND));
		homeAssistUtils.sendMessage(payload(T0 + 20 * SECOND, LEVEL_UP, T0 + 19 * SECOND));
		assertEquals(3, homeAssistUtils.getQueuedCount(connection));

		responseCode = 200;
		endPause();

		assertEquals(4, sentBodies.size());
		assertEquals(List.of(T0 - TICK), trailTimestamps(sentBodies.get(1)));
		assertEquals(List.of(T0 + 9 * SECOND), trailTimestamps(sentBodies.get(2)));
		assertEquals(List.of(T0 + 19 * SECOND), trailTimestamps(sentBodies.get(3)));
	}

	@Test
	public void testCombinedSnapshotStaysWithinTheTrailPointLimit()
	{
		int limit = MessageBuilder.MAX_LOCATION_TRAIL_POINTS;

		responseCode = 500;
		homeAssistUtils.sendMessage(snapshot(T0, ticksBefore(T0, limit - 100)));
		homeAssistUtils.sendMessage(snapshot(T0 + 10 * SECOND, ticksBefore(T0 + 10 * SECOND, 100)));
		assertEquals(1, homeAssistUtils.getQueuedCount(connection));

		homeAssistUtils.sendMessage(snapshot(T0 + 20 * SECOND, T0 + 19 * SECOND));
		assertEquals(2, homeAssistUtils.getQueuedCount(connection));

		responseCode = 200;
		endPause();

		assertEquals(limit, trailTimestamps(sentBodies.get(1)).size());
		assertEquals(List.of(T0 + 19 * SECOND), trailTimestamps(sentBodies.get(2)));
	}

	@Test
	public void testSnapshotsFromDifferentWorldsAreNotCombined()
	{
		responseCode = 500;
		homeAssistUtils.sendMessage(snapshot(T0, T0 - TICK));
		homeAssistUtils.sendMessage(snapshot(T0 + 10 * SECOND, T0 + 9 * SECOND).replace("\"world\":\"302\"", "\"world\":\"303\""));

		assertEquals(2, homeAssistUtils.getQueuedCount(connection));
	}

	@Test
	public void testCombiningKeepsTheNewerSnapshotWhenTheOlderOneComesLast()
	{
		String combined = homeAssistUtils.combineTrailSnapshots(
			snapshot(T0 + 10 * SECOND, T0 + 9 * SECOND),
			snapshot(T0, T0 - TICK));

		assertEquals(List.of(T0 - TICK, T0 + 9 * SECOND), trailTimestamps(combined));
		assertEquals(T0 + 10 * SECOND, timestamp(combined));
	}

	/* ============================
	   404 AND OTHER 4XX
	   ============================ */

	// Home Assistant answers 404 from the moment its web server is up until the integration has registered its endpoints
	@Test
	public void testPayloadAnsweredNotFoundIsResentAfterThePause()
	{
		responseCode = 404;
		homeAssistUtils.sendMessage(payload(T0, LEVEL_UP));

		assertEquals(1, homeAssistUtils.getQueuedCount(connection));
		assertEquals(now + 30 * SECOND, homeAssistUtils.getPausedUntil(connection));

		responseCode = 200;
		endPause();

		assertEquals(2, sentBodies.size());
		assertEquals(sentBodies.get(0), sentBodies.get(1));
		assertEquals(0, homeAssistUtils.getQueuedCount(connection));
	}

	@Test
	public void testQueueIsNotDrainedWhileTheEndpointAnswersNotFound()
	{
		// Deliveries fail while Home Assistant restarts: three payloads with an event wait for it
		responseCode = 500;
		homeAssistUtils.sendMessage(payload(T0, LEVEL_UP));
		homeAssistUtils.sendMessage(payload(T0 + 10 * SECOND, LEVEL_UP));
		homeAssistUtils.sendMessage(payload(T0 + 20 * SECOND, LEVEL_UP));
		assertEquals(3, homeAssistUtils.getQueuedCount(connection));

		// Its web server answers again, but the integration has not registered its endpoints yet
		responseCode = 404;
		endPause();

		assertEquals(2, sentBodies.size());
		assertEquals(3, homeAssistUtils.getQueuedCount(connection));
		assertEquals(now + 60 * SECOND, homeAssistUtils.getPausedUntil(connection));

		responseCode = 200;
		endPause();

		assertEquals(5, sentBodies.size());
		assertEquals(T0, timestamp(sentBodies.get(2)));
		assertEquals(T0 + 10 * SECOND, timestamp(sentBodies.get(3)));
		assertEquals(T0 + 20 * SECOND, timestamp(sentBodies.get(4)));
		assertEquals(0, homeAssistUtils.getQueuedCount(connection));
	}

	// A connection whose address is wrong is answered 404 for as long as the client runs
	@Test
	public void testEndpointThatKeepsAnsweringNotFoundIsRetriedOncePerPause()
	{
		responseCode = 404;
		homeAssistUtils.sendMessage(payload(now, LEVEL_UP));

		long[] expectedPauseSeconds = {30, 60, 120, 240, 480, 600, 600, 600};
		for (long seconds : expectedPauseSeconds)
		{
			assertEquals(now + seconds * SECOND, homeAssistUtils.getPausedUntil(connection));

			// Halfway through the pause, more payloads have been built than the queue holds
			now += seconds * SECOND / 2;
			for (int i = 1; i <= ConnectionBackoff.MAX_QUEUED_PAYLOADS + 10; i++)
			{
				homeAssistUtils.sendMessage(payload(now + i, LEVEL_UP));
			}
			assertEquals(ConnectionBackoff.MAX_QUEUED_PAYLOADS, homeAssistUtils.getQueuedCount(connection));

			endPause();
		}

		// The first attempt and one retry per pause, however many payloads were built meanwhile
		assertEquals(1 + expectedPauseSeconds.length, sentBodies.size());
		assertEquals(1, scheduledRetries.size());

		// The payloads that are still waiting are given up once they are 10 minutes old
		now += ConnectionBackoff.MAX_QUEUE_AGE_MS + 1;
		assertEquals(0, homeAssistUtils.getQueuedCount(connection));
	}

	// A 400 means the endpoint refused that exact payload, so sending it again would only be refused again
	@Test
	public void testPayloadAnsweredBadRequestIsDroppedWithoutARetry()
	{
		responseCode = 400;
		homeAssistUtils.sendMessage(payload(T0, LEVEL_UP));

		assertEquals(1, sentBodies.size());
		assertEquals(0, homeAssistUtils.getQueuedCount(connection));
		assertEquals(0, homeAssistUtils.getPausedUntil(connection));
		assertTrue(scheduledRetries.isEmpty());
	}

	@Test
	public void testQueuedPayloadAnsweredBadRequestIsDroppedAndTheNextOneIsSentAtOnce()
	{
		responseCode = 500;
		homeAssistUtils.sendMessage(payload(T0, LEVEL_UP));
		homeAssistUtils.sendMessage(payload(T0 + 10 * SECOND, LEVEL_UP));
		assertEquals(2, homeAssistUtils.getQueuedCount(connection));

		responseCode = 400;
		endPause();

		assertEquals(3, sentBodies.size());
		assertEquals(T0, timestamp(sentBodies.get(1)));
		assertEquals(T0 + 10 * SECOND, timestamp(sentBodies.get(2)));
		assertEquals(0, homeAssistUtils.getQueuedCount(connection));
		assertEquals(0, homeAssistUtils.getPausedUntil(connection));
	}

	/* ============================
	   HELPERS
	   ============================ */

	// Moves the clock to the end of the current pause and runs the retries that were scheduled for it
	private void endPause()
	{
		now = Math.max(now, homeAssistUtils.getPausedUntil(connection));

		List<Runnable> due = new ArrayList<>(scheduledRetries);
		scheduledRetries.clear();
		due.forEach(Runnable::run);
	}

	// A periodic message without events, with one trail point per given timestamp
	private static String snapshot(long timestamp, long... trailTimestamps)
	{
		return payload(timestamp, "", trailTimestamps);
	}

	private static String payload(long timestamp, String events, long... trailTimestamps)
	{
		StringBuilder trail = new StringBuilder();
		for (long trailTimestamp : trailTimestamps)
		{
			if (trail.length() > 0)
			{
				trail.append(',');
			}
			trail.append("{\"x\":3222,\"y\":3218,\"plane\":0,\"isOnBoat\":false,\"timestamp\":").append(trailTimestamp).append('}');
		}

		return "{"
			+ "\"player\":{"
			+ "\"name\":\"PlayerName\","
			+ "\"world\":\"302\","
			+ "\"location\":{\"x\":3222,\"y\":3218,\"plane\":0,\"isOnBoat\":false},"
			+ "\"locationTrail\":[" + trail + "]"
			+ "},"
			+ "\"events\":[" + events + "],"
			+ "\"timestamp\":" + timestamp
			+ "}";
	}

	// One timestamp per game tick, the last one a tick before the given time
	private static long[] ticksBefore(long timestamp, int count)
	{
		long[] timestamps = new long[count];
		for (int i = 0; i < count; i++)
		{
			timestamps[i] = timestamp - (count - i) * TICK;
		}
		return timestamps;
	}

	private long timestamp(String body)
	{
		return gson.fromJson(body, JsonObject.class).get("timestamp").getAsLong();
	}

	private List<Long> trailTimestamps(String body)
	{
		List<Long> timestamps = new ArrayList<>();
		JsonObject player = gson.fromJson(body, JsonObject.class).getAsJsonObject("player");
		for (JsonElement point : player.getAsJsonArray("locationTrail"))
		{
			timestamps.add(point.getAsJsonObject().get("timestamp").getAsLong());
		}
		return timestamps;
	}
}

package haexporterplugin.utils;

import com.google.gson.JsonObject;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;
import static org.mockito.Mockito.when;

public class HomeAssistUtilsFilterTest extends HomeAssistUtilsTestBase
{
	private static final String PAYLOAD = "{"
		+ "\"player\":{"
		+ "\"name\":\"PlayerName\","
		+ "\"location\":{\"x\":1640,\"y\":9562,\"plane\":0,\"isOnBoat\":false},"
		+ "\"locationTrail\":[{\"x\":1640,\"y\":9562,\"plane\":0,\"isOnBoat\":false,\"timestamp\":1735689600000}]"
		+ "},"
		+ "\"events\":["
		+ "{\"type\":\"levelUp\",\"data\":[{\"skill\":\"Attack\",\"level\":99}]}"
		+ "]}";

	// Either switch being off is enough
	@Test
	public void testLocationSwitchesRemoveLocationAndTrail()
	{
		connection.setIncludeLocation(false);
		assertNoLocation(filter());

		connection.setIncludeLocation(true);
		when(config.includeLocation()).thenReturn(false);
		assertNoLocation(filter());
	}

	@Test
	public void testTrailKeptWhenOtherDataIsFiltered()
	{
		connection.setIncludeInventory(false);
		connection.setIncludeLevelUpEvents(false);

		JsonObject filtered = filter();

		assertEquals(1, filtered.getAsJsonObject("player").getAsJsonArray("locationTrail").size());
		assertEquals(List.of(), eventTypes(filtered));
	}

	private JsonObject filter()
	{
		return gson.fromJson(homeAssistUtils.applyConnectionFilters(PAYLOAD, connection), JsonObject.class);
	}

	private static void assertNoLocation(JsonObject filtered)
	{
		assertFalse(filtered.getAsJsonObject("player").has("location"));
		assertFalse(filtered.getAsJsonObject("player").has("locationTrail"));
		assertEquals(List.of("levelUp"), eventTypes(filtered));
	}

	private static List<String> eventTypes(JsonObject payload)
	{
		List<String> types = new ArrayList<>();
		payload.getAsJsonArray("events").forEach(event -> types.add(event.getAsJsonObject().get("type").getAsString()));
		return types;
	}
}

package haexporterplugin.utils;

import haexporterplugin.HAExporterConfig;
import haexporterplugin.HAExporterPlugin;
import haexporterplugin.TestUtils;
import haexporterplugin.data.HAConnection;
import haexporterplugin.data.PairingException;
import haexporterplugin.data.TokenCallback;
import okhttp3.Request;
import org.junit.Test;

import java.lang.reflect.Proxy;

import static org.junit.Assert.*;

public class HomeAssistUtilsPairingTest extends HomeAssistUtilsTestBase
{
	private static final String VERSION_HEADER = "X-Osrs-Exporter-Version";

	// Backing value for the stored connections config item (see createConfigUtils)
	private String storedConnections = "[]";

	/* ============================
	   VERSION HEADER
	   ============================ */

	@Test
	public void testPairRequestSendsVersionHeader()
	{
		pair(200, "{\"token\":\"abc123\"}");

		Request request = sentRequests.get(0);
		assertEquals("POST", request.method());
		assertEquals("http://ha.local:8123/api/osrs-data/pair", request.url().toString());
		assertEquals(HAExporterPlugin.PLUGIN_VERSION, request.header(VERSION_HEADER));
		assertNull(request.header("X-Osrs-Token"));
	}

	@Test
	public void testEventsRequestSendsVersionHeader()
	{
		Request request = homeAssistUtils.buildRequest("http://ha.local:8123/api/osrs-data/events", "{}", "secret-token");

		assertEquals(HAExporterPlugin.PLUGIN_VERSION, request.header(VERSION_HEADER));
		assertEquals("secret-token", request.header("X-Osrs-Token"));
		assertEquals("application/json", request.header("Content-Type"));
	}

	/* ============================
	   PAIR RESPONSES (END TO END)
	   ============================ */

	@Test
	public void testPairPassesTokenAndSanitizedName()
	{
		assertPaired(pair(200, "{\"token\":\"abc123\"}"), null);
		assertPaired(pair(200, "{\"token\":\"abc123\",\"name\":\"My Server\"}"), "My Server");
		assertPaired(pair(200, "{\"token\":\"abc123\",\"name\":\"<html><b>Evil</b></html>\"}"), "htmlbEvil/b/html");
	}

	@Test
	public void testPairFailureCarriesServerError()
	{
		PairResult result = pair(400, "{\"error\":\"Code expired\"}");

		assertNull(result.token);
		assertTrue(result.failure instanceof PairingException);
		assertEquals("Code expired", ((PairingException) result.failure).getServerMessage());
		assertTrue(result.failure.getMessage().startsWith("Unexpected response"));
	}

	/* ============================
	   PARSING AND SANITIZING
	   ============================ */

	@Test
	public void testParsePairName()
	{
		// Only a string with something left after sanitizing is a name
		for (String name : new String[]{"42", "true", "null", "{\"value\":\"My Server\"}", "[\"My Server\"]", "\"\"", "\"\\t\\n\""})
		{
			assertNull(name, HomeAssistUtils.parsePairName(TestUtils.json("{\"name\":" + name + "}").getAsJsonObject()));
		}
		assertEquals("a".repeat(64), HomeAssistUtils.parsePairName(TestUtils.json("{\"name\":\"" + "a".repeat(100) + "\"}").getAsJsonObject()));
	}

	@Test
	public void testExtractPairError()
	{
		// Only a string in the error field of a JSON object is an error
		String[] withoutError = {null, "", "   ", "Forbidden", "<html><body><h1>502 Bad Gateway</h1></body></html>",
			"{\"error\":\"Code exp", "{}", "{\"detail\":\"Code expired\"}", "[\"error\"]", "\"error\"", "null", "{\"error\":42}",
			"{\"error\":\"   \"}"};
		for (String body : withoutError)
		{
			assertNull(body, HomeAssistUtils.extractPairError(gson, body));
		}
		assertEquals("Code expired.\nRequest a new one.",
			HomeAssistUtils.extractPairError(gson, "{\"error\":\"Code expired.\\r\\nRequest a new one.\\u0007\"}"));
		assertEquals("x".repeat(200), HomeAssistUtils.extractPairError(gson, "{\"error\":\"" + "x".repeat(500) + "\"}"));
	}

	@Test
	public void testSanitizeServerText()
	{
		assertEquals("My Server", HomeAssistUtils.sanitizeServerText(" My\u0000 Serv\u001ber\u007f\t", 64, false));
		assertEquals("ab", HomeAssistUtils.sanitizeServerText("a\nb", 64, false));
		assertEquals("a\nb", HomeAssistUtils.sanitizeServerText("a\r\nb", 64, true));
		assertEquals("htmlscriptx/script", HomeAssistUtils.sanitizeServerText("<html><script>x</script>", 64, true));
		assertEquals("abcde", HomeAssistUtils.sanitizeServerText("abcdefgh", 5, false));
		assertEquals("abc", HomeAssistUtils.sanitizeServerText("abc   def", 5, false));
		assertNull(HomeAssistUtils.sanitizeServerText("  \u0000 <> ", 64, true));
		// Cutting "ab" and an emoji at 3 characters would keep half of the emoji's surrogate pair
		assertEquals("ab", HomeAssistUtils.sanitizeServerText("ab" + new String(Character.toChars(0x1F600)), 3, false));
	}

	/* ============================
	   STORING THE PAIRED CONNECTION
	   ============================ */

	@Test
	public void testAddStoredConnectionUsesName() throws Exception
	{
		ConfigUtils configUtils = createConfigUtils();
		configUtils.addStoredConnection("http://ha.local:8123", "abc123", "My Server");

		HAConnection stored = configUtils.getStoredConnections().get(0);
		assertEquals("abc123", stored.getToken());
		assertEquals("My Server", stored.getFriendlyName());
		assertEquals("My Server", stored.getDisplayName());
	}

	@Test
	public void testAddStoredConnectionWithoutName() throws Exception
	{
		ConfigUtils configUtils = createConfigUtils();
		configUtils.addStoredConnection("http://ha.local:8123", "abc123", null);

		HAConnection stored = configUtils.getStoredConnections().get(0);
		assertNull(stored.getFriendlyName());
		assertEquals("http://ha.local:8123", stored.getDisplayName());
		assertFalse(storedConnections.contains("friendlyName"));
	}

	/* ============================
	   HELPERS
	   ============================ */

	private PairResult pair(int code, String body)
	{
		responseCode = code;
		responseBody = body;

		PairResult result = new PairResult();
		homeAssistUtils.getToken("http://ha.local:8123", "12345", result);
		assertTrue("Pairing callback was not called", result.called);
		return result;
	}

	private static void assertPaired(PairResult result, String name)
	{
		assertNull(result.failure);
		assertEquals("abc123", result.token);
		assertEquals(name, result.name);
	}

	// ConfigUtils only touches the stored connections item, so an in-memory proxy is enough as config
	private ConfigUtils createConfigUtils() throws Exception
	{
		HAExporterConfig storedConfig = (HAExporterConfig) Proxy.newProxyInstance(
			HAExporterConfig.class.getClassLoader(),
			new Class<?>[]{HAExporterConfig.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "homeassistantConnections":
						return storedConnections;
					case "setHomeassistantConnections":
						storedConnections = (String) args[0];
						return null;
					default:
						throw new UnsupportedOperationException(method.getName());
				}
			});

		ConfigUtils configUtils = new ConfigUtils();
		TestUtils.setField(configUtils, "config", storedConfig);
		TestUtils.setField(configUtils, "gson", gson);
		return configUtils;
	}

	private static class PairResult implements TokenCallback
	{
		private boolean called;
		private String token;
		private String name;
		private Exception failure;

		@Override
		public void onSuccess(String token, String name)
		{
			this.called = true;
			this.token = token;
			this.name = name;
		}

		@Override
		public void onFailure(Exception e)
		{
			this.called = true;
			this.failure = e;
		}
	}
}

package haexporterplugin.utils;

import com.google.common.util.concurrent.MoreExecutors;
import com.google.gson.Gson;
import haexporterplugin.HAExporterConfig;
import haexporterplugin.TestUtils;
import haexporterplugin.data.HAConnection;
import okhttp3.Dispatcher;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import okio.Buffer;
import org.junit.Before;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * A real HomeAssistUtils without network or waiting. Every config switch is on and {@link #connection} is the only
 * connection. Every request is answered at once with {@link #responseCode} and {@link #responseBody}, retries wait in
 * {@link #scheduledRetries} and {@link #now} is the clock of the connection's backoff state.
 */
abstract class HomeAssistUtilsTestBase
{
	static final long T0 = 1_700_000_000_000L;
	static final long SECOND = 1000L;

	final Gson gson = new Gson();
	final HAExporterConfig config = TestUtils.configWithEverythingOn();
	final HAConnection connection = new HAConnection("http://ha.local:8123", "secret-token");
	HomeAssistUtils homeAssistUtils;

	long now = T0;
	int responseCode = 200;
	String responseBody = "{}";
	final List<Request> sentRequests = new ArrayList<>();
	final List<String> sentBodies = new ArrayList<>();
	final List<Runnable> scheduledRetries = new ArrayList<>();

	@Before
	public void setUpHomeAssistUtils() throws Exception
	{
		ConfigUtils configUtils = mock(ConfigUtils.class);
		when(configUtils.getStoredConnections()).thenAnswer(invocation -> List.of(connection));

		// The direct executor runs the response callback before the call that sent the request returns
		OkHttpClient okHttpClient = new OkHttpClient.Builder()
			.dispatcher(new Dispatcher(MoreExecutors.newDirectExecutorService()))
			.addInterceptor(chain ->
			{
				Buffer body = new Buffer();
				chain.request().body().writeTo(body);
				sentRequests.add(chain.request());
				sentBodies.add(body.readUtf8());
				return response(chain.request(), responseCode, responseBody);
			})
			.build();

		ScheduledExecutorService executor = mock(ScheduledExecutorService.class);
		when(executor.schedule(any(Runnable.class), anyLong(), any(TimeUnit.class))).thenAnswer(invocation ->
		{
			scheduledRetries.add(invocation.getArgument(0));
			return null;
		});

		homeAssistUtils = new HomeAssistUtils();
		homeAssistUtils.config = config;
		TestUtils.setField(homeAssistUtils, "gson", gson);
		TestUtils.setField(homeAssistUtils, "configUtils", configUtils);
		TestUtils.setField(homeAssistUtils, "okHttpClient", okHttpClient);
		TestUtils.setField(homeAssistUtils, "executor", executor);
		TestUtils.setField(homeAssistUtils, "backoff", new ConnectionBackoff(() -> now));
	}

	static Response response(Request request, int code, String body)
	{
		return new Response.Builder()
			.request(request)
			.protocol(Protocol.HTTP_1_1)
			.code(code)
			.message("Test")
			.body(ResponseBody.create(MediaType.get("application/json"), body))
			.build();
	}
}

